// The manager's option catalog: every server option ARK: Survival Ascended documents, described in
// plain English and given a control the settings page knows how to render.
//
// Sourcing. reference/asa-options.json is a verbatim snapshot of the community wiki's own annotated
// default inis - 346 options, each with its ini file, section, documented default and description.
// Every field below is checked against that snapshot by tools/check-coverage.js, which fails if an
// option exists in the reference and is neither a field here nor a declared entry in
// RAW_ONLY_OPTIONS. Coverage is therefore a checkable fact, and a future ARK release that adds
// options shows up as a failing check rather than as a quietly incomplete screen.
//
// Descriptions. The options people actually tune are written out by hand, each ending in a concrete
// example of what a changed value does. The long tail (map-specific buffs, mesh checking, tribute
// expiry, engine plumbing) carries the wiki's own wording, tidied up.
//
// Ranges. min/max exist to stop a typo, not to express taste, so they are deliberately generous. A
// max that is too low is worse than none at all: the number input clamps to it, so a legitimate
// value silently becomes a different one on save.
//
// Field shape:
//   key           the ini key, spelled as the wiki spells it
//   type          bool | float | int | string | password
//   category      which tab it appears under
//   iniFile       'game' for Game.ini, omitted for GameUserSettings.ini
//   iniSection    only when it is not that file's usual section
//   default       the documented default. A value in parentheses is not a literal: '(none)' means
//                 blank, '(game default)' means the key is absent and the game decides
//   locked        rendered read-only, because ARK Overseer itself depends on the value
//   lockedReason  why, shown under the greyed-out control
//   launchFlag    applied on the command line at launch, never written to an ini
//   help          a gotcha worth saying out loud under the control
//   levelReadout  show the derived max wild creature level under the slider

// SessionName and ServerPassword are both embedded directly into the ?key=value launch connect
// string (see startServer()); a literal "?" in either would be parsed as the start of a new
// key=value pair and silently corrupt the launch command.
const NO_QUESTION_MARK = '^[^?]*$';
const SESSION_NAME_MAX_LENGTH = 60;

const SESSION_NAME_META = {
  maxLength: SESSION_NAME_MAX_LENGTH,
  pattern: NO_QUESTION_MARK,
  patternHelp: 'Cannot contain "?".',
  description: 'The server name shown in the in-game server browser. Example: set to "Neo Olympus" and that is exactly what appears when someone searches the unofficial server list.',
};

const SETTINGS_FIELDS = [
  // ------------------------------------------------------------------ General
  { key: 'ServerPassword', type: 'password', category: 'General', label: 'Join Password', maxLength: 64, pattern: NO_QUESTION_MARK, patternHelp: 'Cannot contain "?" - it breaks the server launch command.', default: '(none)', description: 'Password players must enter to join the server. Leave blank for an open server. Example: set to "friends2026" and only people who know that word can connect.' },
  { key: 'ServerAdminPassword', type: 'password', category: 'General', label: 'Admin Password', maxLength: 64, pattern: NO_QUESTION_MARK, patternHelp: 'Cannot contain "?".', default: '(none)', description: 'The password for admin commands and for RCON, which ARK Overseer uses to control the server. In game, type "enablecheats <password>" in the console to get commands like god and fly.' },
  { key: 'SpectatorPassword', type: 'password', category: 'General', label: 'Spectator Password', maxLength: 64, pattern: NO_QUESTION_MARK, patternHelp: 'Cannot contain "?".', default: '(none)', description: 'Lets a player who is not an admin watch the server without playing. Leave blank and only admins can spectate. Example: set one, and a player typing "requestspectator <password>" in console detaches into a free-roaming camera until they type "stopspectating".' },
  { key: 'MaxPlayers', type: 'int', category: 'General', label: 'Max Players', min: 1, max: 100, step: 1, default: 70, help: 'Actually enforced via the -WinLiveMaxPlayers launch flag, not this ini value directly.', description: 'Maximum simultaneous players allowed on the server. Example: set to 20 and a 21st player trying to join gets a server-full message.' },
  { key: 'ServerPVE', type: 'bool', category: 'General', label: 'PvE Mode', default: false, description: 'When on, players cannot damage each other or take each other\'s structures and tames. Example: with PvE on, two tribes can build side by side and never be raided.' },
  { key: 'ServerHardcore', type: 'bool', category: 'General', label: 'Hardcore Mode', default: false, description: 'Characters revert to level 1 upon death. Example: a level 80 survivor who dies respawns at level 1 with no levels kept.' },
  { key: 'ProximityChat', type: 'bool', category: 'General', label: 'Proximity Chat', default: false, description: 'When on, only players physically near each other can see each other\'s chat messages. Example: a player across the map will not see what you type unless they are standing nearby.' },
  { key: 'ShowMapPlayerLocation', type: 'bool', category: 'General', label: 'Show Player Location on Map', default: true, description: 'When off, hides each player\'s own precise position on their map. Example: opening the map shows the world but not a dot marking exactly where you are.' },
  { key: 'AllowThirdPersonPlayer', type: 'bool', category: 'General', label: 'Allow Third Person', default: true, description: 'When off, disables the third-person camera option for players. Example: pressing the third-person toggle key does nothing and everyone stays locked to first-person view.' },
  { key: 'ServerCrosshair', type: 'bool', category: 'General', label: 'Show Crosshair', default: true, description: 'When off, disables the aiming crosshair for players. Example: aiming a bow shows no crosshair dot to help judge where the shot will land.' },
  { key: 'AllowHitMarkers', type: 'bool', category: 'General', label: 'Show Hit Markers', default: true, description: 'When off, removes the marker that confirms a ranged attack connected. Example: landing an arrow on a distant target gives no on-screen tick, so you judge the hit by the target\'s reaction alone.' },
  { key: 'ShowFloatingDamageText', type: 'bool', category: 'General', label: 'Floating Damage Numbers', default: false, description: 'Shows damage as numbers popping off whatever you hit, the way an RPG does. Example: hitting a Rex for 214 makes "214" float up from it instead of giving no numeric feedback at all.' },
  { key: 'ServerForceNoHUD', type: 'bool', category: 'General', label: 'Hide Creature Name HUD', default: false, description: 'Hides the floating name and health HUD over creatures your tribe does not own. Example: a wild Raptor shows no name or level tag when you look at it, so you have to judge it by eye.' },
  { key: 'PreventSpawnAnimations', type: 'bool', category: 'General', label: 'Skip Wake-Up Animation', default: false, description: 'Players respawn already on their feet instead of playing the wake-up animation. Example: after dying you regain control the instant you spawn rather than watching your survivor sit up first.' },
  { key: 'AllowSharedConnections', type: 'bool', category: 'General', label: 'Allow Steam Family Sharing', default: false, description: 'Lets players whose copy of the game came through Steam family sharing connect. Example: a friend playing on a borrowed copy can join instead of being rejected at the door.' },
  { key: 'DisableBattlEye', type: 'bool', category: 'General', label: 'Disable BattlEye', default: false, launchFlag: true, help: 'Applied via the -NoBattlEye launch flag, not an ini value - like Mods and Max Players.', description: 'Turns off BattlEye anti-cheat for this server. Example: turn this on if BattlEye is blocking a mod or causing false-positive kicks; leave off to keep anti-cheat protection for a public server.' },
  { key: 'bShowCreativeMode', iniFile: 'game', type: 'bool', category: 'General', label: 'Creative Mode Button', default: false, description: 'Adds a creative-mode switch to the pause menu. Example: an admin can flip into creative to build a monument with unlimited resources, then flip back out.' },
  { key: 'bDisablePhotoMode', iniFile: 'game', type: 'bool', category: 'General', label: 'Disable Photo Mode', default: false, description: 'Turns photo mode off entirely. Example: pressing the photo-mode key does nothing instead of detaching a free camera.' },
  { key: 'PhotoModeRangeLimit', iniFile: 'game', type: 'int', category: 'General', label: 'Photo Mode Range Limit', min: 0, max: 100000, step: 100, default: 3000, description: 'How far the photo-mode camera may travel from the player. Example: at 500 the camera stays close enough to frame your own base but cannot be flown across the valley to scout someone else\'s.' },
  { key: 'bUseSingleplayerSettings', iniFile: 'game', type: 'bool', category: 'General', label: 'Use Single Player Settings', default: false, help: 'This rebalances a long list of other rates behind the scenes, so values set elsewhere stop behaving the way their numbers suggest.', description: 'Applies the game\'s own single-player rebalance on top of your settings, intended for a server with very few players. Example: with this on, taming and maturation run far faster than your multipliers alone would explain, because the game is quietly scaling them a second time.' },

  // --------------------------------------------------------------- Difficulty
  { key: 'OverrideOfficialDifficulty', type: 'float', category: 'Difficulty', label: 'Difficulty', min: 0, max: 20, step: 0.2, default: 0.0, levelReadout: true, help: 'Max wild creature level is roughly this value times 30. Zero means no override, which hands the decision to Difficulty Offset below.', description: 'Sets the difficulty value that decides wild creature level ranges and loot quality, overriding the map\'s own default. Example: a value of 5 caps most wild dino levels around 150, while 10 allows levels up to about 300.' },
  { key: 'DifficultyOffset', type: 'float', category: 'Difficulty', label: 'Difficulty Offset', min: 0, max: 1, step: 0.01, default: 1.0, help: 'Only consulted while Difficulty above is 0. This is a 0-to-1 position inside the map\'s own range, not a level multiplier.', description: 'Scales difficulty within whatever range the map allows, as a fraction rather than as a level. Example: at 0.5 wild creatures top out around the middle of the map\'s intended level band instead of at its ceiling.' },

  // -------------------------------------------------------------------- Rates
  { key: 'TamingSpeedMultiplier', type: 'float', category: 'Rates', label: 'Taming Speed Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how quickly wild creatures tame. Example: at 5.0, a tame that normally takes an hour finishes in about 12 minutes.' },
  { key: 'HarvestAmountMultiplier', type: 'float', category: 'Rates', label: 'Harvest Amount Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales resources gained per harvest action. Example: at 3.0, one hit on a tree yields three times the usual wood.' },
  { key: 'HarvestHealthMultiplier', type: 'float', category: 'Rates', label: 'Harvest Health Multiplier', min: 0.1, max: 20, step: 0.1, default: 1.0, help: 'Higher means more strikes per node, which means more total yield from the same tree even before Harvest Amount is considered.', description: 'Scales the health of harvestable things like trees, rocks and carcasses, which is really the number of strikes each one survives. Example: at 2.0 a tree takes twice as many hits to fell, and gives roughly twice as much wood in total.' },
  { key: 'ResourcesRespawnPeriodMultiplier', type: 'float', category: 'Rates', label: 'Resource Respawn Period Multiplier', min: 0.01, max: 10, step: 0.01, default: 1.0, help: 'Lower = resources respawn faster.', description: 'Scales the time between a resource node being harvested and coming back. Example: at 0.5, nodes respawn twice as fast as default.' },
  { key: 'ResourceNoReplenishRadiusPlayers', iniFile: 'game', type: 'float', category: 'Rates', label: 'No-Respawn Radius Around Players', min: 0, max: 10, step: 0.05, default: 1.0, description: 'Scales how close to a player a harvested resource is allowed to grow back. Example: at 0.5 the dead zone around players shrinks by half, so trees reappear much nearer to where someone is standing.' },
  { key: 'ResourceNoReplenishRadiusStructures', iniFile: 'game', type: 'float', category: 'Rates', label: 'No-Respawn Radius Around Structures', min: 0, max: 10, step: 0.05, default: 1.0, help: 'The usual reason to lower this is a base that has permanently sterilised the forest around it.', description: 'Scales how close to a structure a harvested resource is allowed to grow back. Example: at 0.25 trees regrow almost up against your walls instead of leaving a wide bare ring around the base.' },
  { key: 'DinoCountMultiplier', type: 'float', category: 'Rates', label: 'Creature Spawn Count Multiplier', min: 0, max: 10, step: 0.1, default: 1.0, description: 'Scales how many wild creatures spawn across the map. Example: at 0.5, roughly half as many wild dinos populate the map as normal.' },
  { key: 'PlayerHarvestingDamageMultiplier', iniFile: 'game', type: 'float', category: 'Rates', label: 'Player Harvesting Damage Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how much damage a player does to a harvestable node, which sets how fast they strip it. Example: at 3.0 a survivor fells a tree in a third of the swings.' },
  { key: 'DinoHarvestingDamageMultiplier', iniFile: 'game', type: 'float', category: 'Rates', label: 'Creature Harvesting Damage Multiplier', min: 0, max: 100, step: 0.1, default: 3.2, help: 'The game\'s own default here is 3.2, not 1.0 - tames are meant to out-harvest players.', description: 'Scales how much damage a tame does to a harvestable node. Example: at 6.4 a Therizinosaurus clears a berry patch in half the bites it normally would.' },
  { key: 'CropGrowthSpeedMultiplier', iniFile: 'game', type: 'float', category: 'Rates', label: 'Crop Growth Speed Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how fast crops grow in a plot. Example: at 5.0 a plot of berries reaches full yield in about a fifth of the usual time.' },
  { key: 'CropDecaySpeedMultiplier', iniFile: 'game', type: 'float', category: 'Rates', label: 'Crop Decay Speed Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'Higher slows decay down rather than speeding it up, which is the opposite of what the name suggests.', description: 'Scales how long a neglected crop plot survives without water or fertiliser. Example: at 2.0 an unattended plot lasts about twice as long before it withers.' },
  { key: 'PoopIntervalMultiplier', iniFile: 'game', type: 'float', category: 'Rates', label: 'Poop Interval Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'Higher shortens the wait rather than lengthening it.', description: 'Scales how often survivors and tames produce fertiliser. Example: at 2.0 you get droppings about twice as often, which matters on a server that runs on dung beetles.' },
  { key: 'HairGrowthSpeedMultiplier', iniFile: 'game', type: 'float', category: 'Rates', label: 'Hair Growth Speed Multiplier', min: 0, max: 100, step: 0.1, default: 0, help: 'Ascended ships this at 0, so hair and facial hair do not grow at all until you raise it.', description: 'Scales how fast hair and facial hair grow back after cutting. Example: at 1.0 hair grows at the old Survival Evolved rate instead of staying permanently at whatever length it was cut to.' },
  { key: 'UseOptimizedHarvestingHealth', type: 'bool', category: 'Rates', label: 'Optimised Harvesting Health', default: false, help: 'Worth turning on if a high Harvest Amount multiplier is causing server hitches, at the cost of fewer rare drops.', description: 'Trades some rare-item yield for much cheaper harvesting on the server when harvest multipliers are high. Example: on a 10x harvest server this stops each swing from spawning a pile of separate item stacks, at the price of fewer rare finds.' },
  { key: 'ClampResourceHarvestDamage', type: 'bool', category: 'Rates', label: 'Clamp Resource Harvest Damage', default: false, help: 'Expect a noticeable drop in yield if damage multipliers are high, since overkill damage stops counting.', description: 'Caps the damage a tame can do to a resource at whatever health that resource has left, so overkill is wasted rather than converted into extra yield. Example: a Mammoth that one-shots a tree for ten times its health harvests only the tree\'s worth of wood instead of the full swing\'s worth.' },

  // ------------------------------------------------------------- XP & Levels
  { key: 'XPMultiplier', type: 'float', category: 'XP & Levels', label: 'XP Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'This is the global scale. The four multipliers below it split the same XP up by where it came from.', description: 'Scales experience gained from all sources, for players, tribes and tames. Example: at 2.0, killing a creature or crafting an item grants twice the normal XP.' },
  { key: 'GenericXPMultiplier', iniFile: 'game', type: 'float', category: 'XP & Levels', label: 'Passive XP Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales the XP that simply accrues over time for being alive. Example: at 3.0 a survivor idling in base levels three times as fast from passive XP alone.' },
  { key: 'HarvestXPMultiplier', iniFile: 'game', type: 'float', category: 'XP & Levels', label: 'Harvesting XP Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales the XP earned for harvesting. Example: at 5.0 an afternoon of chopping wood is a genuine route to levelling instead of a rounding error.' },
  { key: 'KillXPMultiplier', iniFile: 'game', type: 'float', category: 'XP & Levels', label: 'Kill XP Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales the XP earned for a kill. Example: at 0.5 hunting is worth half as much, which pushes players toward crafting and exploring instead.' },
  { key: 'CraftXPMultiplier', iniFile: 'game', type: 'float', category: 'XP & Levels', label: 'Crafting XP Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales the XP earned for crafting. Example: at 2.0 mass-producing spark powder levels you twice as fast.' },
  { key: 'SpecialXPMultiplier', iniFile: 'game', type: 'float', category: 'XP & Levels', label: 'Special Event XP Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales the XP earned from special-event sources. Example: at 2.0 an event that normally grants a fixed XP reward grants double for its duration.' },
  { key: 'OverrideMaxExperiencePointsPlayer', iniFile: 'game', type: 'int', category: 'XP & Levels', label: 'Player XP Cap', min: 0, max: 10000000, step: 1000, default: '(game default)', help: 'Raising the cap alone does not add levels. Without a matching level ramp the extra XP has nowhere to go.', description: 'Hard cap on total XP a player character can accumulate. Example: set to 500000 and a survivor stops gaining XP there, no matter how many levels the ramp would otherwise allow.' },
  { key: 'OverrideMaxExperiencePointsDino', iniFile: 'game', type: 'int', category: 'XP & Levels', label: 'Creature XP Cap', min: 0, max: 10000000, step: 1000, default: '(game default)', description: 'Hard cap on total XP a tamed creature can accumulate. Example: set to 100000 and a bred Rex stops levelling once it gets there.' },
  { key: 'bAllowSpeedLeveling', iniFile: 'game', type: 'bool', category: 'XP & Levels', label: 'Allow Movement Speed Leveling', default: false, description: 'Lets players and non-flying creatures put levels into Movement Speed. Example: with this off, points spent on speed are simply unavailable and everyone moves at base pace.' },
  { key: 'bAllowFlyerSpeedLeveling', iniFile: 'game', type: 'bool', category: 'XP & Levels', label: 'Allow Flyer Speed Leveling', default: false, help: 'In Ascended this does nothing unless Allow Movement Speed Leveling above is also on.', description: 'Lets flying creatures put levels into Movement Speed. Example: with both this and the general speed setting on, a bred Argentavis can be levelled into a genuinely fast transport.' },
  { key: 'bUseDinoLevelUpAnimations', iniFile: 'game', type: 'bool', category: 'XP & Levels', label: 'Creature Level-Up Animations', default: true, description: 'Plays the celebratory animation when a tame levels. Example: with this off, a Rex levelling mid-fight keeps fighting instead of stopping to roar.' },

  // ------------------------------------------------------- Damage & Resistance
  { key: 'PlayerDamageMultiplier', type: 'float', category: 'Damage & Resistance', label: 'Player Damage Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales damage dealt by players. Example: at 2.0, a hit that normally does 20 damage does 40.' },
  { key: 'PlayerResistanceMultiplier', type: 'float', category: 'Damage & Resistance', label: 'Player Resistance Multiplier', min: 0.01, max: 100, step: 0.01, default: 1.0, help: 'Higher means tougher. Zero would make players take no damage at all, which is why the slider stops just above it.', description: 'Scales damage resistance for players. Example: at 2.0, incoming damage to a player is effectively halved.' },
  { key: 'DinoDamageMultiplier', type: 'float', category: 'Damage & Resistance', label: 'Wild Creature Damage Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales damage dealt by wild creatures. Example: at 0.5 a wild Rex bite that normally does 200 damage does 100.' },
  { key: 'DinoResistanceMultiplier', type: 'float', category: 'Damage & Resistance', label: 'Wild Creature Resistance Multiplier', min: 0.01, max: 100, step: 0.01, default: 1.0, help: 'Higher means tougher wild creatures. This is the field that made everything invulnerable when an absent key was once saved as 0.', description: 'Scales damage resistance for wild creatures. Example: at 2.0, a wild creature takes half the normal damage from any source.' },
  { key: 'TamedDinoDamageMultiplier', type: 'float', category: 'Damage & Resistance', label: 'Tamed Creature Damage Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales damage dealt by tamed creatures. Example: at 1.5 your tamed Rex hits half again as hard as an identical wild one.' },
  { key: 'TamedDinoResistanceMultiplier', type: 'float', category: 'Damage & Resistance', label: 'Tamed Creature Resistance Multiplier', min: 0.01, max: 100, step: 0.01, default: 1.0, description: 'Scales damage resistance for tamed creatures. Example: at 1.5, your tamed Rex survives roughly 50% more incoming damage than an untamed one would.' },
  { key: 'StructureDamageMultiplier', type: 'float', category: 'Damage & Resistance', label: 'Structure Damage Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales damage dealt by structures such as spike walls and turrets. Example: at 2.0, a spike wall deals twice its normal damage to anything that touches it.' },
  { key: 'StructureResistanceMultiplier', type: 'float', category: 'Damage & Resistance', label: 'Structure Resistance Multiplier', min: 0.01, max: 100, step: 0.01, default: 1.0, description: 'Scales damage resistance for structures. Example: at 2.0, a wooden wall absorbs twice as many hits before breaking.' },
  { key: 'MaxFallSpeedMultiplier', iniFile: 'game', type: 'float', category: 'Damage & Resistance', label: 'Fall Damage Threshold Multiplier', min: 0.1, max: 100, step: 0.1, default: 1.0, description: 'Scales how fast you have to be falling before fall damage starts. Example: at 2.0 a drop that would normally break your legs is survivable, because the game tolerates twice the descent speed first.' },

  // ----------------------------------------------------------------- Survival
  { key: 'PlayerCharacterFoodDrainMultiplier', type: 'float', category: 'Survival', label: 'Player Food Drain Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how fast players get hungry. Example: at 2.0, food drains twice as fast, so you need to eat about twice as often.' },
  { key: 'PlayerCharacterWaterDrainMultiplier', type: 'float', category: 'Survival', label: 'Player Water Drain Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how fast players get thirsty. Example: at 0.5, water drains at half speed, so you can go roughly twice as long between drinks.' },
  { key: 'PlayerCharacterStaminaDrainMultiplier', type: 'float', category: 'Survival', label: 'Player Stamina Drain Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how fast players burn stamina. Example: at 0.5 a survivor can sprint about twice as far before having to stop.' },
  { key: 'PlayerCharacterHealthRecoveryMultiplier', type: 'float', category: 'Survival', label: 'Player Health Recovery Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how fast players heal. Example: at 3.0 you recover from a bad fight in a third of the time, without needing as much medical brew.' },
  { key: 'DinoCharacterFoodDrainMultiplier', type: 'float', category: 'Survival', label: 'Creature Food Drain Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'This also changes taming times, since a wild creature eats its taming food on the same clock.', description: 'Scales how fast creatures get hungry. Example: at 0.5, a tamed dino\'s food bar lasts about twice as long before needing a refill.' },
  { key: 'DinoCharacterStaminaDrainMultiplier', type: 'float', category: 'Survival', label: 'Creature Stamina Drain Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how fast creatures burn stamina. Example: at 0.5 a flyer crosses roughly twice the distance before it has to land.' },
  { key: 'DinoCharacterHealthRecoveryMultiplier', type: 'float', category: 'Survival', label: 'Creature Health Recovery Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how fast creatures heal. Example: at 5.0 a wounded Rex is back to full health in a fraction of the usual time.' },
  { key: 'TamedDinoCharacterFoodDrainMultiplier', iniFile: 'game', type: 'float', category: 'Survival', label: 'Tamed Creature Food Drain Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'Stacks with the general Creature Food Drain multiplier above, and applies only to tames.', description: 'Scales how fast tamed creatures specifically consume food. Example: at 0.25 a full trough feeds your tames roughly four times as long.' },
  { key: 'WildDinoCharacterFoodDrainMultiplier', iniFile: 'game', type: 'float', category: 'Survival', label: 'Wild Creature Food Drain Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'This is the honest way to speed up passive taming without touching tamed creatures\' upkeep.', description: 'Scales how fast wild creatures consume food, which is also how fast they eat taming food. Example: at 3.0 a wild creature works through narcotics and kibble three times as fast, so tames finish sooner.' },
  { key: 'TamedDinoTorporDrainMultiplier', iniFile: 'game', type: 'float', category: 'Survival', label: 'Tamed Creature Torpor Drain Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how fast tamed creatures shake off torpor. Example: at 2.0 a tame knocked out by a Beelzebufo wakes in half the time.' },
  { key: 'WildDinoTorporDrainMultiplier', iniFile: 'game', type: 'float', category: 'Survival', label: 'Wild Creature Torpor Drain Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'Lower this to make knockout taming more forgiving, since torpor lasts longer between tranq shots.', description: 'Scales how fast wild creatures lose torpor while unconscious. Example: at 0.5 a knocked-out Rex stays down twice as long, so you need far less narcotic to keep it under.' },
  { key: 'BaseTemperatureMultiplier', iniFile: 'game', type: 'float', category: 'Survival', label: 'Base Temperature Multiplier', min: 0, max: 10, step: 0.05, default: 1.0, description: 'Scales the map\'s ambient temperature. Example: at 0.5 the whole world runs cold, so heat stroke stops being a threat and insulation matters much more.' },
  { key: 'OxygenSwimSpeedStatMultiplier', type: 'float', category: 'Survival', label: 'Oxygen Swim Speed Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how much swim speed a player gains per level spent in Oxygen. Example: at 5.0 an oxygen-heavy build actually swims noticeably fast, instead of the small gain the stat normally gives.' },
  { key: 'AllowFlyingStaminaRecovery', type: 'bool', category: 'Survival', label: 'Recover Stamina While Standing On a Flyer', default: false, description: 'Lets a player regain stamina while standing on a flying mount. Example: a passenger riding on a Quetzal platform recovers stamina in the air instead of having to land first.' },
  { key: 'bForceCanRideFliers', type: 'bool', category: 'Survival', label: 'Force Flyers Rideable', default: '(map default)', help: 'Leave this alone unless you mean it. Setting it off disables flyers on every map, including the ones where they normally work.', description: 'Overrides whether flyers can be ridden on maps that normally forbid it. Example: turn it on for Aberration and Argentavis mounts work there, which the map is not designed around.' },
  { key: 'bDisableDinoRiding', iniFile: 'game', type: 'bool', category: 'Survival', label: 'Disable Creature Riding', default: false, description: 'Stops players from riding tames at all. Example: tames can still fight and carry cargo, but everyone travels on foot.' },
  { key: 'PreventDiseases', type: 'bool', category: 'Survival', label: 'Prevent Diseases', default: false, description: 'Removes diseases from the server, which in practice means Swamp Fever. Example: wading through the swamp no longer risks a permanent illness.' },
  { key: 'NonPermanentDiseases', type: 'bool', category: 'Survival', label: 'Diseases Are Not Permanent', default: false, description: 'Makes otherwise permanent diseases wear off on respawn. Example: a survivor who catches Swamp Fever can clear it by dying, instead of carrying it for the rest of the character\'s life.' },
  { key: 'bUseCorpseLocator', iniFile: 'game', type: 'bool', category: 'Survival', label: 'Show Corpse Locator Beam', default: true, description: 'Marks your own body with a green light beam after you die. Example: with this off, dying far from base means finding your gear from memory alone.' },
  { key: 'ImplantSuicideCD', type: 'float', category: 'Survival', label: 'Implant Respawn Cooldown (seconds)', min: 0, max: 86400, step: 60, default: 28800, description: 'How long a player must wait between uses of the implant\'s Respawn option. Example: at 300 a survivor stuck in terrain can free themselves every five minutes instead of waiting the default eight hours.' },

  // ----------------------------------------------------------------- Breeding
  { key: 'bDisableDinoBreeding', iniFile: 'game', type: 'bool', category: 'Breeding', label: 'Disable Breeding', default: false, description: 'Stops tames from being bred at all. Example: with this on, a mated pair never produces an egg or a gestation, so every creature on the server has to be tamed from the wild.' },
  { key: 'MatingIntervalMultiplier', iniFile: 'game', type: 'float', category: 'Breeding', label: 'Mating Interval Multiplier', min: 0, max: 100, step: 0.01, default: 1.0, help: 'Lower = a pair becomes ready to breed again sooner.', description: 'Scales the cooldown a female must sit through before she can mate again. Example: at 0.1 a Rex that normally needs a full day between clutches is ready again in a couple of hours.' },
  { key: 'MatingSpeedMultiplier', iniFile: 'game', type: 'float', category: 'Breeding', label: 'Mating Speed Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'Higher = the mating bar itself fills faster.', description: 'Scales how long the act of mating takes once a pair has started. Example: at 2.0 a pair completes mating in half the usual time, so you are not standing around waiting for the bar.' },
  { key: 'EggHatchSpeedMultiplier', iniFile: 'game', type: 'float', category: 'Breeding', label: 'Egg Hatch / Gestation Speed Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'This covers live gestation too, not just eggs - a Rex pregnancy runs on the same clock.', description: 'Scales how quickly a fertilised egg hatches or a pregnancy comes to term. Example: at 10.0 an egg that normally needs a couple of hours hatches in about twelve minutes.' },
  { key: 'LayEggIntervalMultiplier', iniFile: 'game', type: 'float', category: 'Breeding', label: 'Egg Lay Interval Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'Higher lengthens the wait between eggs. Lower it to farm eggs faster.', description: 'Scales how often creatures drop ordinary unfertilised eggs. Example: at 0.25 a pen of Dodos produces eggs about four times as fast, which is what a kibble operation runs on.' },
  { key: 'BabyMatureSpeedMultiplier', iniFile: 'game', type: 'float', category: 'Breeding', label: 'Baby Mature Speed Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'Raise this and you must lower Baby Cuddle Interval to match, or 100% imprint becomes impossible.', description: 'Scales how quickly a baby creature grows to adulthood. Example: at 10.0, a baby that normally takes several days to mature grows up in a few hours.' },
  { key: 'BabyFoodConsumptionSpeedMultiplier', iniFile: 'game', type: 'float', category: 'Breeding', label: 'Baby Food Consumption Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'Lower this alongside a raised maturation speed, or a fast-growing baby starves between trough refills.', description: 'Scales how fast a baby eats through its food. Example: at 0.5 a newborn Rex empties the trough half as quickly, so it can be left alone for longer stretches.' },
  { key: 'BabyCuddleIntervalMultiplier', iniFile: 'game', type: 'float', category: 'Breeding', label: 'Baby Cuddle Interval Multiplier', min: 0, max: 10, step: 0.01, default: 1.0, help: 'Lower = imprint requests come more often.', description: 'Scales the time between a baby\'s imprint requests. Should be lowered to match a faster maturation speed, or 100% imprint can become mathematically impossible. Example: at 0.5, imprint requests come twice as often, roughly every few minutes instead of every ten.' },
  { key: 'BabyImprintAmountMultiplier', iniFile: 'game', type: 'float', category: 'Breeding', label: 'Baby Imprint Amount Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how much imprint percentage each successful care action grants. Example: at 2.0, each cuddle or feed grants twice the imprint percentage toward 100%.' },
  { key: 'BabyCuddleGracePeriodMultiplier', iniFile: 'game', type: 'float', category: 'Breeding', label: 'Baby Cuddle Grace Period Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how long you may ignore an imprint request before imprint quality starts falling. Example: at 3.0 you get three times the usual window to answer a cuddle request before losing progress.' },
  { key: 'BabyCuddleLoseImprintQualitySpeedMultiplier', iniFile: 'game', type: 'float', category: 'Breeding', label: 'Imprint Quality Loss Speed Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'Set to 0 and a missed request costs nothing, which is the forgiving option for a server nobody watches overnight.', description: 'Scales how fast imprint quality drains once the grace period has run out. Example: at 0.25 a missed request bleeds imprint away four times more slowly, so an overnight gap is recoverable.' },
  { key: 'BabyImprintingStatScaleMultiplier', iniFile: 'game', type: 'float', category: 'Breeding', label: 'Imprint Stat Bonus Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'Zero switches the whole imprint stat system off, which is one way to stop imprinting from deciding fights.', description: 'Scales how much imprint quality actually improves a creature\'s stats. Example: at 2.0 a fully imprinted Rex is dramatically stronger than an unimprinted one, rather than moderately so.' },
  { key: 'AllowAnyoneBabyImprintCuddle', type: 'bool', category: 'Breeding', label: 'Anyone Can Imprint', default: false, description: 'Lets any tribe member answer a baby\'s care requests, not only the survivor it first imprinted on. Example: with this on, whoever is online can keep a raise going instead of the imprint stalling until one specific person logs in.' },
  { key: 'DisableImprintDinoBuff', type: 'bool', category: 'Breeding', label: 'Disable Imprint Rider Buff', default: false, description: 'Removes the extra damage and resistance a creature gives the specific survivor who imprinted it. Example: with this on, any rider gets the same performance out of a bred Rex, so raised creatures can be shared freely.' },
  { key: 'PreventMateBoost', type: 'bool', category: 'Breeding', label: 'Prevent Mate Boost', default: false, description: 'Turns off the stat bonus a pair of mated creatures gives each other. Example: with this on, two Rexes fighting side by side hit no harder than either would alone.' },
  { key: 'FreezeReaperPregnancy', type: 'bool', category: 'Breeding', label: 'Freeze Reaper Pregnancy', default: false, help: 'Undocumented by Wildcard.', description: 'Halts the Reaper King pregnancy timer and its experience gain. Example: with this on, a survivor carrying a Reaper stays pregnant indefinitely instead of the timer running down.' },
  { key: 'CryoHospitalMatingCooldownReduction', type: 'float', category: 'Breeding', label: 'Cryo Hospital Mating Cooldown Reduction', min: 0, max: 100, step: 0.1, default: 2.0, help: 'This one is undocumented on the wiki; the value below is the shipped default.', description: 'How much faster a creature\'s mating cooldown runs down while it sits in a cryo hospital. Example: at 4.0 parking a female in the hospital burns off her cooldown four times as fast as leaving her in the pen.' },
  { key: 'AdjustableMutagenSpawnDelayMultiplier', iniFile: 'game', type: 'float', category: 'Breeding', label: 'Mutagen Spawn Delay Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales the delay between Mutagen spawn attempts, which the game makes every eight hours on a dedicated server. Example: at 0.25 Mutagen becomes available roughly every two hours instead.' },

  // ----------------------------------------------------------- Taming & Tames
  { key: 'bDisableDinoTaming', iniFile: 'game', type: 'bool', category: 'Taming & Tames', label: 'Disable Taming', default: false, description: 'Stops players from taming wild creatures. Example: with this on and breeding left enabled, the only new tames are bred from whatever the server already has.' },
  { key: 'PassiveTameIntervalMultiplier', iniFile: 'game', type: 'float', category: 'Taming & Tames', label: 'Passive Tame Interval Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'Higher shortens the wait between feeds rather than lengthening it.', description: 'Scales how often a passive-tame creature will accept its next hand-fed item. Example: at 3.0 a Gigantopithecus asks for food three times as often, so a passive tame finishes far sooner.' },
  { key: 'AllowRaidDinoFeeding', type: 'bool', category: 'Taming & Tames', label: 'Allow Titanosaur Permanent Taming', default: false, help: 'The Island only spawns three Titanosaurs, so three permanent ones effectively ends Titanosaur spawns.', description: 'Lets Titanosaurs be fed, which makes them permanent tames instead of ones that decay away. Example: with this on, a tamed Titanosaur can be kept and used indefinitely rather than being a single-use siege engine.' },
  { key: 'RaidDinoCharacterFoodDrainMultiplier', type: 'float', category: 'Taming & Tames', label: 'Titanosaur Food Drain Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how fast a raid creature such as a Titanosaur burns food. Example: at 0.25 a Titanosaur needs feeding a quarter as often, which makes keeping one practical.' },
  { key: 'bAllowUnclaimDinos', iniFile: 'game', type: 'bool', category: 'Taming & Tames', label: 'Allow Unclaiming Tames', default: true, description: 'Lets players release a tame back to unclaimed. Example: with this off, nobody can dump an unwanted creature for another tribe to pick up, which closes a common way of laundering tames.' },
  { key: 'MaxTamedDinos', type: 'float', category: 'Taming & Tames', label: 'Max Tamed Creatures (server-wide)', min: 0, max: 20000, step: 50, default: 5000, description: 'Global cap on how many tamed creatures can exist on the server at once. Example: at 500, once tribes collectively own 500 tames, no one can tame or breed a new one until the count drops.' },
  { key: 'MaxPersonalTamedDinos', type: 'int', category: 'Taming & Tames', label: 'Max Tamed Creatures Per Tribe', min: 0, max: 20000, step: 10, default: 0, help: 'Zero means no per-tribe limit. Official runs 500 on PvE and 300 on PvP.', description: 'Cap on how many tames a single tribe may own. Example: at 300 a tribe at its limit must cryo or cull something before it can tame anything new, even if the server-wide cap is nowhere near.' },
  { key: 'MaxTamedDinos_SoftTameLimit', type: 'int', category: 'Taming & Tames', label: 'Soft Tame Limit', min: 0, max: 20000, step: 50, default: 5000, help: 'Only does anything when Destroy Tames Over Soft Limit below is on.', description: 'The count past which tames get flagged for cryopodding rather than blocked outright. Example: at 4000 the four-thousand-and-first tame is marked "For Cryo" with a countdown instead of the server simply refusing new tames.' },
  { key: 'DestroyTamesOverTheSoftTameLimit', type: 'bool', category: 'Taming & Tames', label: 'Destroy Tames Over Soft Limit', default: false, help: 'This deletes creatures. The countdown below is the only warning players get.', description: 'Turns the soft limit into an enforced one: flagged tames are destroyed when their countdown expires. Example: with this on, a tame over the limit shows a timer, and if nobody cryopods it in time the server deletes it.' },
  { key: 'MaxTamedDinos_SoftTameLimit_CountdownForDeletionDuration', type: 'int', category: 'Taming & Tames', label: 'Soft Limit Deletion Countdown (seconds)', min: 0, max: 2592000, step: 3600, default: 604800, description: 'How long a flagged tame survives before deletion. Example: the default 604800 is seven days, so a tribe has a week to cryopod anything the soft limit flagged.' },
  { key: 'DestroyTamesOverLevelClamp', iniFile: 'game', type: 'int', category: 'Taming & Tames', label: 'Destroy Tames Over Level', min: 0, max: 5000, step: 5, default: 0, help: 'Zero disables this. Official uses 450. It runs at server start and it deletes, so a wrong value here is expensive.', description: 'Deletes any tame above this level when the server starts, as an anti-cheat measure against impossibly levelled creatures. Example: at 450 a legitimately bred and imprinted creature is safe, while a hacked level-1000 Rex is removed on the next restart.' },
  { key: 'PersonalTamedDinosSaddleStructureCost', type: 'int', category: 'Taming & Tames', label: 'Platform Saddle Tame Slot Cost', min: 0, max: 1000, step: 1, default: 0, description: 'How many tame slots a platform saddle carrying structures counts as, against the per-tribe limit. Example: at 20 a Quetzal with a built platform costs a tribe twenty slots instead of one, which discourages flying bases.' },
  { key: 'bUseTameLimitForStructuresOnly', iniFile: 'game', type: 'bool', category: 'Taming & Tames', label: 'Tame Limit Applies to Platforms Only', default: false, description: 'Counts only platform-saddle creatures and rafts against the tame limit. Example: with this on, a tribe can keep an unlimited breeding pen but is still restricted on flying and floating bases.' },
  { key: 'AutoDestroyDecayedDinos', type: 'bool', category: 'Taming & Tames', label: 'Auto-Destroy Decayed Tames', default: false, description: 'Removes decayed claimable tames when the world loads rather than leaving them standing to be claimed. Example: an abandoned tribe\'s pen of creatures disappears at the next restart instead of becoming free tames for whoever finds it.' },
  { key: 'DisableDinoDecayPvE', type: 'bool', category: 'Taming & Tames', label: 'Disable Tame Decay (PvE)', default: false, description: 'Stops tames from decaying on a PvE server. Example: with this on, going on holiday for a month does not put your creatures at risk of becoming claimable.' },
  { key: 'PvEDinoDecayPeriodMultiplier', type: 'float', category: 'Taming & Tames', label: 'Tame Decay Period Multiplier (PvE)', min: 0, max: 100, step: 0.1, default: 1.0, help: 'Requires Disable Tame Decay (PvE) above to be off, or there is no decay clock for this to scale.', description: 'Scales how long a PvE tame goes untouched before it decays. Example: at 3.0 creatures survive three times as long unvisited before they are at risk.' },
  { key: 'PvPDinoDecay', type: 'bool', category: 'Taming & Tames', label: 'Tame Decay During Offline Raid Protection (PvP)', default: false, description: 'Lets tames decay in PvP while offline raid prevention is shielding them. Example: with this on, a tribe cannot hide behind offline protection forever without logging in to maintain its creatures.' },

  // -------------------------------------------------------- Structures & Ops
  { key: 'TheMaxStructuresInRange', type: 'int', category: 'Structures & Ops', label: 'Max Structures In Range', min: 100, max: 100000, step: 100, default: 10500, description: 'Maximum number of structures allowed within a fixed radius, to limit the performance cost of a mega-base. Example: at 6000, a sprawling base needing 10,500 pieces hits a hard wall and cannot place more in that area.' },
  { key: 'MaxStructuresInSmallRadius', type: 'int', category: 'Structures & Ops', label: 'Max Structures In Small Radius', min: 0, max: 10000, step: 5, default: 0, help: 'Zero disables this second, tighter limit. Official uses 40. Undocumented by Wildcard.', description: 'A tighter structure cap applied inside the small radius set below, on top of the range limit above. Example: at 40 a player cannot stack more than forty pieces right on top of themselves, which is what turret towers and pillar spam rely on.' },
  { key: 'RadiusStructuresInSmallRadius', type: 'float', category: 'Structures & Ops', label: 'Small Radius Size (Unreal units)', min: 0, max: 100000, step: 25, default: 0.0, help: 'Only matters when Max Structures In Small Radius above is non-zero. Official uses 225. Undocumented by Wildcard.', description: 'How large the "small radius" is, measured in Unreal units. Example: at 225 the tighter cap applies within roughly a large room around the player rather than across the whole base.' },
  { key: 'IgnoreLimitMaxStructuresInRangeTypeFlag', type: 'bool', category: 'Structures & Ops', label: 'Ignore Decorative Structure Limit', default: false, description: 'Removes the separate cap of 150 decorative structures such as flags, signs and dermis. Example: with this on, a trophy hall can hold every dermis a tribe has collected instead of stopping at 150.' },
  { key: 'PerPlatformMaxStructuresMultiplier', type: 'float', category: 'Structures & Ops', label: 'Per-Platform Max Structures Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales the maximum number of structures placeable on a single platform saddle or raft. Example: at 2.0, a platform saddle that normally holds 20 structures can hold 40.' },
  { key: 'MaxPlatformSaddleStructureLimit', type: 'int', category: 'Structures & Ops', label: 'Max Platformed Creatures On Server', min: 0, max: 10000, step: 5, default: 75, help: 'This is a count of platform creatures and rafts server-wide, not structures per platform. Each one costs performance.', description: 'How many platform-saddled creatures and rafts may exist on the map at once. Example: at 10 the server allows ten built-on rafts or Quetzals in total, and the eleventh cannot be built on.' },
  { key: 'MaxGateFrameOnSaddles', type: 'int', category: 'Structures & Ops', label: 'Max Gateways Per Platform Saddle', min: 0, max: 100, step: 1, default: 0, help: 'Zero means no specific gateway limit.', description: 'Caps how many gateways can go on a platform saddle, the usual ingredient in a flying trap. Example: at 2 a player cannot build a third gateway on their Quetzal platform.' },
  { key: 'bAllowPlatformSaddleMultiFloors', iniFile: 'game', type: 'bool', category: 'Structures & Ops', label: 'Allow Multi-Floor Platforms', default: false, description: 'Lets platform saddles carry more than one floor of structures. Example: with this on, a Bronto platform can have an upper deck instead of being limited to a single level.' },
  { key: 'OverrideStructurePlatformPrevention', type: 'bool', category: 'Structures & Ops', label: 'Allow Turrets On Platform Saddles', default: false, description: 'Makes turrets and spikes buildable and functional on platform saddles. Example: with this on, a Quetzal can carry working auto-turrets, which changes PvP considerably.' },
  { key: 'bFlyerPlatformAllowUnalignedDinoBasing', iniFile: 'game', type: 'bool', category: 'Structures & Ops', label: 'Allow Unallied Tames On Flying Platforms', default: false, description: 'Lets any tame that is not allied stand on a flying platform in mid-air. Example: with this on, another tribe\'s creature can hitch a ride on your airborne Quetzal.' },
  { key: 'MaxTrainCars', type: 'int', category: 'Structures & Ops', label: 'Max Train Cars', min: 0, max: 100, step: 1, default: 8, description: 'How many cars a single train may pull. Example: at 20 a long cargo train is possible, at the cost of the extra load a moving structure that size puts on the server.' },
  { key: 'AlwaysAllowStructurePickup', type: 'bool', category: 'Structures & Ops', label: 'Always Allow Structure Pickup', default: false, description: 'Removes the time limit on the quick structure pick-up feature. Example: a foundation placed a week ago can still be instantly picked back up instead of needing to be demolished.' },
  { key: 'StructurePickupTimeAfterPlacement', type: 'float', category: 'Structures & Ops', label: 'Structure Pickup Window (seconds)', min: 0, max: 3600, step: 5, default: 30.0, description: 'How long after placing a structure it can be instantly picked back up. Example: at 30, you have 30 seconds after placing a wall to pick it back up before you would need to demolish it instead.' },
  { key: 'StructurePickupHoldDuration', type: 'float', category: 'Structures & Ops', label: 'Structure Pickup Hold Duration (seconds)', min: 0, max: 10, step: 0.1, default: 0.5, description: 'How long the pick-up key must be held before a structure comes up. Example: at 0 pick-up is instant on tap, which is quicker to build with and much easier to do by accident.' },
  { key: 'ForceAllStructureLocking', type: 'bool', category: 'Structures & Ops', label: 'Lock New Structures By Default', default: false, description: 'Every structure is created locked rather than open. Example: a newly placed storage box starts locked to your tribe, so you cannot forget to secure it.' },
  { key: 'bDisableStructurePlacementCollision', iniFile: 'game', type: 'bool', category: 'Structures & Ops', label: 'Allow Structures To Clip Terrain', default: false, description: 'Lets structures sink into the landscape instead of being blocked by it. Example: with this on, a foundation can be levelled into a hillside rather than left floating on one corner.' },
  { key: 'bIgnoreStructuresPreventionVolumes', iniFile: 'game', type: 'bool', category: 'Structures & Ops', label: 'Ignore No-Build Zones', default: false, description: 'Allows building in the areas the maps normally forbid, such as around obelisks, the Aberration portal, and Genesis mission volumes. Example: with this on, a tribe can wall in an obelisk, which also means they can wall other players out of a transfer point.' },
  { key: 'EnableExtraStructurePreventionVolumes', type: 'bool', category: 'Structures & Ops', label: 'Extra No-Build Zones', default: false, description: 'Blocks building in extra resource-rich areas, chiefly The Island\'s major mountains. Example: with this on, nobody can wall off the metal-rich peaks and hold the map\'s best resources.' },
  { key: 'PvEAllowStructuresAtSupplyDrops', type: 'bool', category: 'Structures & Ops', label: 'Allow Building At Supply Drops (PvE)', default: false, description: 'Permits building near supply-drop points on a PvE server. Example: with this on, a base can be built right on a drop, which is convenient and also lets one tribe monopolise the loot.' },
  { key: 'AllowIntegratedSPlusStructures', type: 'bool', category: 'Structures & Ops', label: 'Allow Built-In S+ Structures', default: true, description: 'Keeps the structures adopted from the Structures Plus mod available. Example: turn this off only if you would rather run the standalone S+ mod and avoid two versions of the same structures.' },
  { key: 'bPassiveDefensesDamageRiderlessDinos', iniFile: 'game', type: 'bool', category: 'Structures & Ops', label: 'Spikes Damage Riderless Creatures', default: false, description: 'Lets spike walls hurt wild and unridden creatures. Example: with this on, spikes around a base actually kill the wild Raptors that wander into them instead of only hurting mounted players.' },
  { key: 'DinoTurretDamageMultiplier', iniFile: 'game', type: 'float', category: 'Structures & Ops', label: 'Turret Damage To Creatures Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales the damage turrets do to creatures specifically. Example: at 3.0 a turret line shreds an incoming Rex push far faster without also becoming stronger against players on foot.' },
  { key: 'bLimitTurretsInRange', iniFile: 'game', type: 'bool', category: 'Structures & Ops', label: 'Limit Turrets In Range', default: true, description: 'Keeps the cap on how many automated turrets, Plant Species X included, may sit in one area. Example: with this off, a tribe can stack turrets without limit, which is both a balance and a performance decision.' },
  { key: 'LimitTurretsNum', iniFile: 'game', type: 'int', category: 'Structures & Ops', label: 'Max Turrets In Range', min: 0, max: 10000, step: 5, default: 100, description: 'How many turrets are allowed inside the turret range below. Example: at 40 a defensive line is much thinner than official\'s 100, which favours attackers.' },
  { key: 'LimitTurretsRange', iniFile: 'game', type: 'float', category: 'Structures & Ops', label: 'Turret Limit Range (Unreal units)', min: 0, max: 100000, step: 500, default: 10000.0, description: 'The radius over which turrets are counted toward the limit. Example: at 20000 the cap covers twice the area, so turrets in two nearby bases start counting against each other.' },
  { key: 'bHardLimitTurretsInRange', iniFile: 'game', type: 'bool', category: 'Structures & Ops', label: 'Retroactive Turret Hard Limit', default: false, help: 'Retroactive: this affects turrets that are already built, not only new ones.', description: 'Applies the turret limit to existing turrets as well as new ones. Example: with this on, a base that was already over the limit has its extra turrets disabled rather than grandfathered in.' },
  { key: 'LimitGeneratorsNum', iniFile: 'game', type: 'int', category: 'Structures & Ops', label: 'Max Generators In Range', min: 0, max: 1000, step: 1, default: 3, description: 'How many generators may sit within the generator range below. Example: official allows 3, which stops a tribe from powering a fortress with a dozen redundant generators.' },
  { key: 'LimitGeneratorsRange', iniFile: 'game', type: 'int', category: 'Structures & Ops', label: 'Generator Limit Range (Unreal units)', min: 0, max: 100000, step: 500, default: 15000, description: 'The radius over which generators are counted toward the limit. Example: at 15000 two bases built close together share one generator allowance.' },
  { key: 'StructureDamageRepairCooldown', iniFile: 'game', type: 'int', category: 'Structures & Ops', label: 'Repair Cooldown After Damage (seconds)', min: 0, max: 3600, step: 10, default: 180, help: 'Zero disables the cooldown, which lets defenders repair walls mid-raid.', description: 'How long after taking damage a structure must wait before it can be repaired. Example: at 0 a defender can patch a wall while it is still being hit, which makes raiding much harder.' },
  { key: 'DisableStructureDecayPvE', type: 'bool', category: 'Structures & Ops', label: 'Disable Structure Decay (PvE)', default: false, description: 'Stops player structures from gradually decaying. Example: with this on, a base left alone for months is still standing when its owner comes back.' },
  { key: 'PvEStructureDecayPeriodMultiplier', type: 'float', category: 'Structures & Ops', label: 'Structure Decay Period Multiplier (PvE)', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how long structures take to decay. Example: at 2.0 all decay timers double, so an abandoned base takes twice as long to become demolishable.' },
  { key: 'PvPStructureDecay', type: 'bool', category: 'Structures & Ops', label: 'Structure Decay During Offline Raid Protection (PvP)', default: false, description: 'Lets structures decay in PvP while offline raid prevention is active. Example: with this on, an inactive tribe\'s protected base still ages away instead of standing shielded forever.' },
  { key: 'AutoDestroyOldStructuresMultiplier', type: 'float', category: 'Structures & Ops', label: 'Auto-Destroy Old Structures Multiplier', min: 0, max: 100, step: 0.1, default: 0.0, help: 'Zero disables auto-destruction entirely. This is a multiplier of the claim period, not a number of days.', description: 'Auto-destroys structures once enough time has passed with no tribe nearby, expressed as a multiple of the claim period. Example: at 1.0 an abandoned base is removed automatically once it has been unclaimed for that full period.' },
  { key: 'OnlyAutoDestroyCoreStructures', type: 'bool', category: 'Structures & Ops', label: 'Auto-Destroy Core Structures Only', default: false, description: 'Exempts non-core structures from auto-destruction, though they still go if the floor beneath them does. Example: with this on, walls and ceilings survive on their own, and only foundations and pillars are removed outright.' },
  { key: 'OnlyDecayUnsnappedCoreStructures', type: 'bool', category: 'Structures & Ops', label: 'Decay Unsnapped Core Structures Only', default: false, help: 'This is the targeted answer to lone pillar and foundation spam.', description: 'Limits decay to core structures that are not snapped to anything else. Example: a single pillar planted to claim land decays away while a real base, whose pieces are all snapped together, does not.' },
  { key: 'FastDecayUnsnappedCoreStructures', type: 'bool', category: 'Structures & Ops', label: 'Fast-Decay Unsnapped Core Structures', default: false, description: 'Puts lone foundations, pillars, fences and Tek dedicated storage on the much shorter fast-decay clock set below. Example: with this on, land-claim pillar spam disappears in hours instead of weeks.' },
  { key: 'FastDecayInterval', iniFile: 'game', type: 'int', category: 'Structures & Ops', label: 'Fast Decay Interval (seconds)', min: 0, max: 2592000, step: 3600, default: 43200, description: 'The decay period used for fast-decay structures. Example: the default 43200 is twelve hours, so a stray pillar is gone by the next day.' },
  { key: 'MaxStructuresToProcess', type: 'int', category: 'Structures & Ops', label: 'Max Structures Processed Per Tick', min: 0, max: 100000, step: 100, default: 0, help: 'Zero keeps the engine default. This is a performance dial, not a gameplay one.', description: 'Caps how many structures the server works through in a single tick when culling or rebuilding its building graph. Example: on a server that stutters near huge bases, a finite value here spreads that work over more ticks instead of doing it in one lump.' },
  { key: 'AutoSavePeriodMinutes', type: 'float', category: 'Structures & Ops', label: 'Auto-Save Period (minutes)', min: 1, max: 240, step: 1, default: 15, description: 'How often the server automatically saves the world to disk. Example: at 5, the world saves every 5 minutes instead of every 15, reducing potential progress loss from a crash.' },
  { key: 'KickIdlePlayersPeriod', type: 'float', category: 'Structures & Ops', label: 'Kick Idle Players After (seconds)', min: 0, max: 86400, step: 60, default: 3600, description: 'How long an inactive player can stay connected before being kicked. Example: at 600, a player who alt-tabs and does not touch their character for 10 minutes gets disconnected.' },

  // --------------------------------------------------------------------- PvP
  { key: 'PreventOfflinePvP', type: 'bool', category: 'PvP', label: 'Offline Raid Prevention', default: false, description: 'Makes a tribe\'s characters, creatures and structures invulnerable once every member has logged off. Example: with this on, a tribe cannot be raided overnight while nobody is around to defend.' },
  { key: 'PreventOfflinePvPInterval', type: 'float', category: 'PvP', label: 'Offline Raid Protection Delay (seconds)', min: 0, max: 86400, step: 5, default: 0.0, help: 'A delay of zero means protection snaps on the instant the last member disconnects, which lets a raid target log off to escape.', description: 'How long after the last member logs off before offline protection engages. Example: at 900 a tribe stays raidable for fifteen minutes, so disconnecting mid-raid is not an escape.' },
  { key: 'PreventOfflinePvPConnectionInvincibleInterval', iniFile: 'game', type: 'float', category: 'PvP', label: 'Spawn-In Invincibility (seconds)', min: 0, max: 600, step: 1, default: 5.0, description: 'How long a player cannot be damaged immediately after logging in. Example: at 15 a player who logs into a base under attack gets a moment to react instead of dying on the loading screen.' },
  { key: 'bIncreasePvPRespawnInterval', iniFile: 'game', type: 'bool', category: 'PvP', label: 'Escalating PvP Respawn Timer', default: true, description: 'Adds extra respawn delay when a player is repeatedly killed by the same enemy tribe. Example: with this on, being farmed at a spawn point costs the victim more time on each death, which discourages camping.' },
  { key: 'IncreasePvPRespawnIntervalBaseAmount', iniFile: 'game', type: 'float', category: 'PvP', label: 'PvP Respawn Penalty Base (seconds)', min: 0, max: 3600, step: 5, default: 60.0, description: 'The extra respawn time added by the escalating timer. Example: at 60 the first repeat death costs an extra minute before the multiplier below compounds it.' },
  { key: 'IncreasePvPRespawnIntervalMultiplier', iniFile: 'game', type: 'float', category: 'PvP', label: 'PvP Respawn Penalty Multiplier', min: 0, max: 100, step: 0.1, default: 2.0, description: 'How much the respawn penalty compounds on each repeat death. Example: at 2.0 the delay doubles each time, so a fourth death in a row is a long wait.' },
  { key: 'IncreasePvPRespawnIntervalCheckPeriod', iniFile: 'game', type: 'float', category: 'PvP', label: 'PvP Respawn Penalty Window (seconds)', min: 0, max: 86400, step: 10, default: 300.0, description: 'The window within which repeat deaths count as repeats. Example: at 300 two deaths five minutes apart escalate, while deaths an hour apart each start fresh.' },
  { key: 'PvPZoneStructureDamageMultiplier', iniFile: 'game', type: 'float', category: 'PvP', label: 'Cave Structure Damage Multiplier', min: 0, max: 100, step: 0.1, default: 6.0, help: 'The game\'s own default is 6.0, so cave bases are deliberately fragile. Set 1.0 to make them as tough as surface bases.', description: 'Scales the damage structures take inside caves. Example: at 1.0 a cave base is exactly as durable as one built on the surface, instead of taking six times the damage.' },
  { key: 'AllowCaveBuildingPvP', type: 'bool', category: 'PvP', label: 'Allow Cave Building (PvP)', default: true, description: 'Permits building inside caves on a PvP server. Example: with this off, caves stay open ground that nobody can wall off and hold.' },
  { key: 'AllowCaveBuildingPvE', type: 'bool', category: 'PvP', label: 'Allow Cave Building (PvE)', default: false, description: 'Permits building inside caves on a PvE server. Example: with this on, a tribe can claim an artifact cave, which also blocks everyone else from the artifact.' },
  { key: 'AllowFlyerCarryPvE', type: 'bool', category: 'PvP', label: 'Allow Flyers To Carry Wild Creatures (PvE)', default: false, description: 'Lets flying creatures pick up wild creatures in PvE. Example: with this on, an Argentavis can lift a wild Raptor away from your base instead of having to fight it on the ground.' },
  { key: 'AllowMultipleAttachedC4', type: 'bool', category: 'PvP', label: 'Allow Multiple C4 Per Creature', default: false, description: 'Lets more than one C4 charge be attached to a single creature. Example: with this on, one suicide runner can carry enough charges to breach a thick wall, which speeds raids up considerably.' },
  { key: 'IgnorePVPMountedWeaponryRestrictions', iniFile: 'game', type: 'bool', category: 'PvP', label: 'Ignore Mounted Weaponry Restrictions', default: false, help: 'Wildcard has published nothing about this one; the wiki has no description for it either.', description: 'Lifts the PvP restrictions on using weaponry while mounted. Example: with this on, weapons the game normally blocks from being fired off a mount become usable, so expect mounted combat to behave differently from official.' },
  { key: 'bDisableFriendlyFire', iniFile: 'game', type: 'bool', category: 'PvP', label: 'Disable Friendly Fire', default: false, description: 'Stops tribe mates, their tames and their structures from damaging each other. Example: with this on, a stray shotgun blast in a crowded base hurts nobody on your own side.' },
  { key: 'bPvEDisableFriendlyFire', iniFile: 'game', type: 'bool', category: 'PvP', label: 'Disable Friendly Fire (PvE)', default: false, description: 'The same protection, applied specifically on a PvE server. Example: with this on, tribe mates cannot accidentally kill each other\'s tames while clearing a pen.' },
  { key: 'EnablePvPGamma', type: 'bool', category: 'PvP', label: 'Allow Gamma Command (PvP)', default: false, description: 'Permits the console gamma command on a PvP server. Example: with this off, nobody can brighten their screen to see through night or a cave\'s darkness.' },
  { key: 'DisablePvEGamma', type: 'bool', category: 'PvP', label: 'Block Gamma Command (PvE)', default: false, description: 'Blocks the console gamma command on a PvE server. Example: with this on, night is genuinely dark for everyone and torches matter.' },
  { key: 'bAutoPvETimer', iniFile: 'game', type: 'bool', category: 'PvP', label: 'Scheduled PvE Window', default: false, description: 'Switches a PvPvE server into PvE between the two times set below. Example: with this on, raiding is only possible outside the protected hours, so players can build unmolested during the day.' },
  { key: 'bAutoPvEUseSystemTime', iniFile: 'game', type: 'bool', category: 'PvP', label: 'PvE Window Uses Real Clock', default: false, description: 'Reads the scheduled PvE window against the server\'s real clock instead of in-game world time. Example: with this on, the window means 9pm to 9am where the server sits, which is far easier for players to plan around.' },
  { key: 'AutoPvEStartTimeSeconds', iniFile: 'game', type: 'float', category: 'PvP', label: 'PvE Window Start (seconds past midnight)', min: 0, max: 86400, step: 900, default: 0.0, help: 'Seconds past midnight, so 9pm is 75600.', description: 'When the scheduled PvE window opens. Example: 75600 starts protection at 9pm.' },
  { key: 'AutoPvEStopTimeSeconds', iniFile: 'game', type: 'float', category: 'PvP', label: 'PvE Window End (seconds past midnight)', min: 0, max: 86400, step: 900, default: 0.0, help: 'Seconds past midnight, so 9am is 32400.', description: 'When the scheduled PvE window closes and raiding resumes. Example: 32400 ends protection at 9am.' },

  // ------------------------------------------------------------------ Tribes
  { key: 'MaxNumberOfPlayersInTribe', iniFile: 'game', type: 'int', category: 'Tribes', label: 'Max Players Per Tribe', min: 0, max: 500, step: 1, default: 0, help: 'Zero means no limit. A value of 1 effectively turns tribes off.', description: 'How many survivors may belong to one tribe. Example: at 6 a large alliance has to split into several tribes rather than absorbing everyone into one.' },
  { key: 'TribeMergeAllowed', type: 'bool', category: 'Tribes', label: 'Allow Tribe Merges', default: true, help: 'Undocumented by Wildcard.', description: 'Lets two tribes combine into one. Example: with this off, a tribe cap cannot be worked around by merging several small tribes together.' },
  { key: 'TribeMergeCooldown', type: 'float', category: 'Tribes', label: 'Tribe Merge Cooldown (seconds)', min: 0, max: 2592000, step: 3600, default: 0.0, help: 'Official uses 86400, a full day. Undocumented by Wildcard.', description: 'How long a tribe must wait between merges. Example: at 86400 a tribe can only merge once a day, which stops repeated merging being used to dodge limits.' },
  { key: 'TribeNameChangeCooldown', type: 'float', category: 'Tribes', label: 'Tribe Name Change Cooldown (minutes)', min: 0, max: 200000, step: 15, default: 15.0, help: 'This one is in minutes, unlike its neighbours. Official uses 172800, which is two days.', description: 'How long a tribe must wait between name changes. Example: at 172800 a tribe cannot keep renaming itself to hide from the people it just raided.' },
  { key: 'TribeSlotReuseCooldown', iniFile: 'game', type: 'float', category: 'Tribes', label: 'Tribe Slot Reuse Cooldown (seconds)', min: 0, max: 2592000, step: 600, default: 0.0, description: 'How long a vacated tribe slot stays locked before someone new can fill it. Example: at 3600 a tribe that kicks a member waits an hour before recruiting a replacement, so the member cap cannot be rotated through freely.' },
  { key: 'MaxTribeLogs', iniFile: 'game', type: 'int', category: 'Tribes', label: 'Tribe Log Entries', min: 0, max: 10000, step: 10, default: 400, description: 'How many tribe log entries each tribe keeps. Example: at 1000 a raided tribe can still scroll back to what happened days ago instead of losing it to newer entries.' },
  { key: 'TribeLogDestroyedEnemyStructures', type: 'bool', category: 'Tribes', label: 'Log Enemy Structures You Destroyed', default: false, description: 'Records structures your tribe destroyed in the victim\'s tribe log. Example: with this on, a raided tribe can see exactly what was broken and by whom.' },
  { key: 'PreventOutOfTribePinCodeUse', type: 'bool', category: 'Tribes', label: 'Block PIN Use By Non-Tribe Players', default: false, help: 'Undocumented by Wildcard.', description: 'Stops players outside the owning tribe from using PIN codes on doors, storage and elevators. Example: with this on, a shared PIN cannot be passed around to let outsiders into a base.' },
  { key: 'PreventTribeAlliances', type: 'bool', category: 'Tribes', label: 'Prevent Tribe Alliances', default: false, description: 'Stops tribes from forming formal alliances. Example: with this off on a small server, two allied tribes can effectively double their limits.' },
  { key: 'MaxAlliancesPerTribe', iniFile: 'game', type: 'int', category: 'Tribes', label: 'Max Alliances Per Tribe', min: 0, max: 100, step: 1, default: '(game default)', description: 'How many alliances a single tribe may belong to. Example: at 1 a tribe must pick one ally rather than joining every alliance on the server.' },
  { key: 'MaxTribesPerAlliance', iniFile: 'game', type: 'int', category: 'Tribes', label: 'Max Tribes Per Alliance', min: 0, max: 100, step: 1, default: '(game default)', description: 'How many tribes may sit inside one alliance. Example: at 2 an alliance is a pact between two tribes rather than a server-wide bloc.' },
  { key: 'bPvEAllowTribeWar', iniFile: 'game', type: 'bool', category: 'Tribes', label: 'Allow Declared Tribe Wars (PvE)', default: true, description: 'Lets two PvE tribes formally declare war on each other for an agreed period. Example: with this on, two tribes can arrange a proper fight without the whole server becoming PvP.' },
  { key: 'bPvEAllowTribeWarCancel', iniFile: 'game', type: 'bool', category: 'Tribes', label: 'Allow Cancelling a Declared War', default: false, description: 'Lets an agreed war be called off before it starts. Example: with this on, a tribe that thinks better of a war it agreed to can back out during the run-up.' },
  { key: 'TribeTowerBonusMultiplier', iniFile: 'game', type: 'float', category: 'Tribes', label: 'Tribe Tower Bonus Multiplier', min: 0, max: 100, step: 0.1, default: 2.0, description: 'Scales the bonus a Tribe Tower grants. Example: at 4.0 the tower is twice as valuable as the game\'s already doubled default, which makes holding one a real objective.' },

  // -------------------------------------------------------- Items & Crafting
  { key: 'ItemStackSizeMultiplier', type: 'float', category: 'Items & Crafting', label: 'Item Stack Size Multiplier', min: 0.1, max: 100, step: 0.1, default: 1.0, help: 'Items with a hard-coded stack size of one, like most saddles, are unaffected.', description: 'Scales every default stack size on the server. Example: at 5.0 a stack of stone holds 500 instead of 100, which cuts base storage and hauling down enormously.' },
  { key: 'GlobalSpoilingTimeMultiplier', iniFile: 'game', type: 'float', category: 'Items & Crafting', label: 'Spoiling Time Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'Higher means food lasts longer, not spoils faster.', description: 'Scales how long perishable food keeps. Example: at 3.0 meat in a preserving bin lasts three times as long, so a supply run covers more days.' },
  { key: 'GlobalItemDecompositionTimeMultiplier', iniFile: 'game', type: 'float', category: 'Items & Crafting', label: 'Dropped Item Lifetime Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how long dropped items and loot bags survive on the ground. Example: at 5.0 a loot bag from a death waits five times as long, which makes recovering a body far more forgiving.' },
  { key: 'GlobalCorpseDecompositionTimeMultiplier', iniFile: 'game', type: 'float', category: 'Items & Crafting', label: 'Corpse Lifetime Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how long player and creature corpses remain. Example: at 3.0 a dead Rex stays harvestable three times as long, so a big kill is worth returning to.' },
  { key: 'UseCorpseLifeSpanMultiplier', iniFile: 'game', type: 'float', category: 'Items & Crafting', label: 'Corpse and Loot Box Lifespan Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'Overlaps with the two multipliers above; set one and check the result in game rather than assuming they compose cleanly.', description: 'Scales corpse and dropped-box lifespan. Example: at 2.0 both bodies and the boxes they leave behind last twice as long.' },
  { key: 'ClampItemSpoilingTimes', type: 'bool', category: 'Items & Crafting', label: 'Clamp Item Spoiling Times', default: false, description: 'Forces every item\'s spoil timer down to its legitimate maximum. Example: turn this on after an infinite-spoil exploit, and hoarded food that would never rot starts rotting again.' },
  { key: 'ClampItemStats', type: 'bool', category: 'Items & Crafting', label: 'Clamp Item Stats', default: false, help: 'The actual caps come from ItemStatClamps entries, which are set by editing the INI file itself.', description: 'Enables stat clamping for items, using the clamp table set in the raw ini. Example: with this on and clamps configured, an impossibly rolled 1500% damage blueprint is pulled back down to the server\'s ceiling.' },
  { key: 'bAllowCustomRecipes', iniFile: 'game', type: 'bool', category: 'Items & Crafting', label: 'Allow Custom Recipes', default: true, description: 'Keeps the custom cooking and recipe system, including skill-based results, available. Example: with this off, nobody can write their own recipes and cooking is limited to the built-in dishes.' },
  { key: 'CustomRecipeEffectivenessMultiplier', iniFile: 'game', type: 'float', category: 'Items & Crafting', label: 'Custom Recipe Effectiveness Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how potent custom recipes are. Example: at 3.0 a player-written stew restores three times as much, which makes cooking a genuinely worthwhile speciality.' },
  { key: 'CustomRecipeSkillMultiplier', iniFile: 'game', type: 'float', category: 'Items & Crafting', label: 'Custom Recipe Skill Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how much the author\'s crafting speed level counts when a custom recipe is created. Example: at 2.0 a high-crafting-skill chef produces markedly better recipes than a novice.' },
  { key: 'CraftingSkillBonusMultiplier', iniFile: 'game', type: 'float', category: 'Items & Crafting', label: 'Crafting Skill Bonus Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales the bonus gained from levelling Crafting Skill. Example: at 3.0 points spent in crafting yield much better item quality, so a dedicated crafter is worth having in a tribe.' },
  { key: 'bAllowUnlimitedRespecs', iniFile: 'game', type: 'bool', category: 'Items & Crafting', label: 'Allow Unlimited Mindwipes', default: false, description: 'Removes the 24-hour cooldown on Mindwipe Tonic. Example: with this on, a player can re-spec for a boss fight and re-spec back afterwards on the same evening.' },
  { key: 'bAutoUnlockAllEngrams', iniFile: 'game', type: 'bool', category: 'Items & Crafting', label: 'Auto-Unlock All Engrams', default: false, help: 'This overrides the engram override lists in the raw ini entirely.', description: 'Unlocks every engram for everyone. Example: with this on, a new player can craft anything their level allows without spending engram points at all.' },
  { key: 'bOnlyAllowSpecifiedEngrams', iniFile: 'game', type: 'bool', category: 'Items & Crafting', label: 'Only Allow Specified Engrams', default: false, help: 'Needs an engram override list in the raw ini to be useful; on its own it hides nearly everything.', description: 'Hides every engram that is not explicitly listed in the engram overrides, and blocks the items and blueprints behind them. Example: with a curated list, a primitive-only server can remove firearms and Tek from the game entirely.' },
  { key: 'SupplyCrateLootQualityMultiplier', iniFile: 'game', type: 'float', category: 'Items & Crafting', label: 'Supply Crate Loot Quality Multiplier', min: 1, max: 5, step: 0.1, default: 1.0, help: 'The game only honours 1.0 to 5.0 here. Difficulty also feeds into the result.', description: 'Raises the quality of items rolled in supply drops. Example: at 3.0 a red drop routinely yields blueprints worth keeping instead of mostly junk.' },
  { key: 'FishingLootQualityMultiplier', iniFile: 'game', type: 'float', category: 'Items & Crafting', label: 'Fishing Loot Quality Multiplier', min: 1, max: 5, step: 0.1, default: 1.0, help: 'The game only honours 1.0 to 5.0 here.', description: 'Raises the quality of items pulled out of the water. Example: at 4.0 fishing becomes a real source of good blueprints rather than a novelty.' },
  { key: 'bDisableLootCrates', iniFile: 'game', type: 'bool', category: 'Items & Crafting', label: 'Disable Loot Crates', default: false, help: 'Artifact crates still spawn regardless of this.', description: 'Stops loot crates from spawning. Example: with this on, gear has to be crafted or raided for, because the map stops handing out blueprints.' },
  { key: 'RandomSupplyCratePoints', type: 'bool', category: 'Items & Crafting', label: 'Randomise Supply Drop Locations', default: false, help: 'Known to make Ragnarok artifacts unreachable while it is on.', description: 'Puts supply drops in random places instead of fixed ones. Example: with this on, nobody can build a base on top of a known red-drop spawn and farm it.' },
  { key: 'AllowCrateSpawnsOnTopOfStructures', type: 'bool', category: 'Items & Crafting', label: 'Allow Supply Crates On Structures', default: false, description: 'Lets airdropped supply crates land on top of structures rather than being blocked by them. Example: with this off, roofing over a drop point stops the drop, which is the usual way of denying it to others.' },
  { key: 'LimitNonPlayerDroppedItemsCount', iniFile: 'game', type: 'int', category: 'Items & Crafting', label: 'Max Non-Player Dropped Items In Range', min: 0, max: 100000, step: 50, default: 0, help: 'Zero means no limit. Official uses 600. This is a performance guard against dropped-item spam.', description: 'Caps how many non-player dropped items may sit within the range set below. Example: at 600 the ground around a mass-kill site stops accumulating loot bags indefinitely.' },
  { key: 'LimitNonPlayerDroppedItemsRange', iniFile: 'game', type: 'int', category: 'Items & Crafting', label: 'Non-Player Dropped Items Range (Unreal units)', min: 0, max: 100000, step: 100, default: 0, help: 'Official uses 1600.', description: 'The radius over which the dropped-item cap above is measured. Example: at 1600 the cap applies within roughly a base-sized area rather than the whole map.' },
  { key: 'FuelConsumptionIntervalMultiplier', iniFile: 'game', type: 'float', category: 'Items & Crafting', label: 'Fuel Consumption Interval Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how often fuel-burning structures consume a unit of fuel. Example: at 0.5 a forge or generator burns through its fuel twice as slowly.' },
  { key: 'GlobalPoweredBatteryDurabilityDecreasePerSecond', iniFile: 'game', type: 'float', category: 'Items & Crafting', label: 'Battery Drain Per Second', min: 0, max: 100, step: 0.1, default: 3.0, description: 'How fast charge batteries are used up in electrical objects. Example: at 1.0 a battery lasts three times as long as the game\'s default, which makes off-grid power practical.' },

  // --------------------------------------------------------------- Cryopods
  // These three deployment gates are independent of PvE mode. ASA gates cryopod deployment behind a
  // powered cryofridge, an enemy-structure proximity check, and a no-platform-saddle rule regardless
  // of whether the server is PvE, so a PvE server still refuses to throw a pod in the field until
  // these are turned off explicitly.
  { key: 'DisableCryopodFridgeRequirement', type: 'bool', category: 'Cryopods', label: 'No Cryofridge Needed to Deploy', default: false, description: 'When on, creatures can be released from a cryopod anywhere, with no powered cryofridge in range. Example: you find a spot to build far from base and can throw out your tames immediately instead of hauling a fridge and a generator there first.' },
  { key: 'DisableCryopodEnemyCheck', type: 'bool', category: 'Cryopods', label: 'Allow Deploy Near Foreign Structures', default: false, description: 'When on, the check that blocks releasing a cryopod near structures you do not own is skipped. Example: you can throw out a tame beside an abandoned base you stumbled across instead of being told the area is blocked.' },
  { key: 'AllowCryoFridgeOnSaddle', type: 'bool', category: 'Cryopods', label: 'Cryofridge on Platform Saddles', default: false, description: 'When on, a cryofridge can be built on a platform saddle or raft. Example: a Bronto or Quetzal platform can carry a working fridge, so a mobile base keeps pods charged on the move.' },
  { key: 'EnableCryoSicknessPVE', type: 'bool', category: 'Cryopods', label: 'Cryo Sickness (PvE)', default: false, description: 'Applies the cooldown timer when a creature is deployed out of a pod. Example: with this on, a tame thrown out mid-fight is briefly useless instead of instantly ready.' },
  { key: 'EnableCryopodNerf', type: 'bool', category: 'Cryopods', label: 'Cryopod Deployment Penalty', default: false, help: 'The wiki\'s own description of this key contradicts itself, so confirm the behaviour on your own server before building rules around it. The three values below are what it configures.', description: 'Turns on the post-deployment penalty for a creature released from a cryopod, configured by the three settings below. Example: with this on and the values set, a tame thrown into a raid deals less and takes more damage for a while, which is what stops pod-dumping from winning fights outright.' },
  { key: 'CryopodNerfDuration', type: 'float', category: 'Cryopods', label: 'Cryopod Penalty Duration (seconds)', min: 0, max: 3600, step: 1, default: 0.0, description: 'How long the deployment penalty lasts. Example: at 20 a creature thrown from a pod spends twenty seconds weakened before it fights normally.' },
  { key: 'CryopodNerfDamageMult', type: 'float', category: 'Cryopods', label: 'Cryopod Penalty Damage Multiplier', min: 0, max: 1, step: 0.01, default: 0.01, help: 'A fraction of normal output, so the shipped 0.01 means one per cent of usual damage while the penalty is running.', description: 'How much damage a freshly deployed creature deals during the penalty. Example: at 0.25 it hits at a quarter strength until the timer expires.' },
  { key: 'CryopodNerfIncomingDamageMultPercent', type: 'float', category: 'Cryopods', label: 'Cryopod Penalty Incoming Damage', min: 0, max: 10, step: 0.01, default: 0.0, description: 'How much extra damage a freshly deployed creature takes during the penalty. Example: at 1.0 it takes double damage while the timer runs, so dumping pods into a turret line is punished.' },
  { key: 'CryoHospitalHoursToRegenHP', type: 'float', category: 'Cryopods', label: 'Cryo Hospital Hours To Heal', min: 0, max: 168, step: 0.5, default: 1.0, help: 'Undocumented by Wildcard; the wiki lists no description for the cryo hospital settings.', description: 'Hours in a cryo hospital needed to bring a creature back to full health. Example: at 0.5 a wounded tame parked in the hospital is fully healed in half an hour.' },
  { key: 'CryoHospitalHoursToRegenFood', type: 'float', category: 'Cryopods', label: 'Cryo Hospital Hours To Refill Food', min: 0, max: 168, step: 0.5, default: 24.0, help: 'Undocumented by Wildcard.', description: 'Hours in a cryo hospital needed to refill a creature\'s food. Example: at 4 a starving tame comes out fed after an afternoon rather than a full day.' },
  { key: 'CryoHospitalHoursToDrainTorpor', type: 'float', category: 'Cryopods', label: 'Cryo Hospital Hours To Clear Torpor', min: 0, max: 168, step: 0.5, default: 1.0, help: 'Undocumented by Wildcard.', description: 'Hours in a cryo hospital needed to clear a creature\'s torpor. Example: at 0.25 a knocked-out tame is awake again within fifteen minutes of being stored.' },

  // --------------------------------------------------------------- Transfers
  { key: 'noTributeDownloads', type: 'bool', category: 'Transfers', label: 'Block All Cross-ARK Downloads', default: false, description: 'Blocks every kind of download from ARK Data. Example: with this on, nobody can bring a fully levelled character or a bred army in from another server.' },
  { key: 'PreventDownloadSurvivors', type: 'bool', category: 'Transfers', label: 'Block Survivor Downloads', default: false, description: 'Blocks downloading survivors specifically. Example: with this on, everyone starts a fresh character here even if they have a level 105 survivor stored elsewhere.' },
  { key: 'PreventDownloadDinos', type: 'bool', category: 'Transfers', label: 'Block Creature Downloads', default: false, description: 'Blocks downloading creatures specifically. Example: with this on, tames have to be earned on this map rather than imported.' },
  { key: 'PreventDownloadItems', type: 'bool', category: 'Transfers', label: 'Block Item Downloads', default: false, description: 'Blocks downloading items and resources specifically. Example: with this on, nobody can import a stack of Tek gear into an otherwise primitive server.' },
  { key: 'PreventUploadSurvivors', type: 'bool', category: 'Transfers', label: 'Block Survivor Uploads', default: false, description: 'Blocks uploading survivors to ARK Data. Example: with this on, a character created here stays here.' },
  { key: 'PreventUploadDinos', type: 'bool', category: 'Transfers', label: 'Block Creature Uploads', default: false, description: 'Blocks uploading creatures to ARK Data. Example: with this on, a bred bloodline cannot be exported off the server.' },
  { key: 'PreventUploadItems', type: 'bool', category: 'Transfers', label: 'Block Item Uploads', default: false, description: 'Blocks uploading items to ARK Data. Example: with this on, resources farmed here cannot be shipped to another map.' },
  { key: 'CrossARKAllowForeignDinoDownloads', type: 'bool', category: 'Transfers', label: 'Allow Foreign Creature Downloads On Aberration', default: false, description: 'Lets creatures that are not native to Aberration be downloaded there. Example: with this on, a flyer can be brought to Aberration, which the map is deliberately built without.' },
  { key: 'MinimumDinoReuploadInterval', type: 'float', category: 'Transfers', label: 'Creature Re-Upload Cooldown (seconds)', min: 0, max: 604800, step: 3600, default: 0.0, help: 'Official uses 43200, twelve hours.', description: 'How long before a creature may be uploaded again. Example: at 43200 a tame cannot be bounced between servers more than twice a day, which is what stops transfer-dodging during a raid.' },
  { key: 'MaxTributeCharacters', type: 'int', category: 'Transfers', label: 'Uploaded Survivor Slots', min: 10, max: 1000, step: 1, default: 10, help: 'Anything below the default is rejected by the game. Raising it has been reported to corrupt cluster data, so move it carefully.', description: 'How many survivors may sit in ARK Data at once. Example: at 20 a player can keep two characters parked between servers instead of ten.' },
  { key: 'MaxTributeDinos', type: 'int', category: 'Transfers', label: 'Uploaded Creature Slots', min: 20, max: 1000, step: 1, default: 20, help: 'Anything below the default is rejected. Reports put the safe ceiling around 273; beyond that cluster data has been seen to corrupt.', description: 'How many creatures may sit in ARK Data at once. Example: at 100 a tribe can move a breeding line across in one trip rather than five.' },
  { key: 'MaxTributeItems', type: 'int', category: 'Transfers', label: 'Uploaded Item Slots', min: 50, max: 1000, step: 1, default: 50, help: 'Anything below the default is rejected. Reports put the safe ceiling around 154.', description: 'How many item and resource stacks may sit in ARK Data at once. Example: at 150 a full inventory of gear transfers in a single load.' },
  { key: 'TributeCharacterExpirationSeconds', type: 'int', category: 'Transfers', label: 'Uploaded Survivor Expiry (seconds)', min: 0, max: 2592000, step: 3600, default: 0, help: 'Zero or negative means uploaded survivors never expire.', description: 'How long an uploaded survivor waits in ARK Data before being discarded. Example: at 86400 a character left in transit for more than a day is gone.' },
  { key: 'TributeDinoExpirationSeconds', type: 'int', category: 'Transfers', label: 'Uploaded Creature Expiry (seconds)', min: 3600, max: 2592000, step: 3600, default: 86400, help: 'Zero or less reverts to the default rather than disabling expiry.', description: 'How long an uploaded creature waits in ARK Data before being discarded. Example: the default 86400 gives you a day to pick a tame back up on the destination server.' },
  { key: 'TributeItemExpirationSeconds', type: 'int', category: 'Transfers', label: 'Uploaded Item Expiry (seconds)', min: 3600, max: 2592000, step: 3600, default: 86400, help: 'Zero or less reverts to the default rather than disabling expiry.', description: 'How long uploaded items wait in ARK Data before being discarded. Example: at 604800 a stash in transit survives a week, so a break from playing does not cost the gear.' },

  // ----------------------------------------------------------------- Bunkers
  // Ascended's bunker settings. Wildcard has published nothing on any of these and the wiki carries
  // no description for them, so each one below says plainly what its name governs and no more.
  { key: 'LimitBunkersPerTribe', type: 'bool', category: 'Bunkers', label: 'Limit Bunkers Per Tribe', default: true, help: 'Undocumented by Wildcard.', description: 'Caps how many bunkers one tribe may own, using the number below. Example: with this off a tribe can build bunkers without limit.' },
  { key: 'LimitBunkersPerTribeNum', type: 'int', category: 'Bunkers', label: 'Max Bunkers Per Tribe', min: 0, max: 100, step: 1, default: 3, help: 'Undocumented by Wildcard. Only applies while the limit above is on.', description: 'How many bunkers a single tribe may own. Example: at 1 each tribe gets one bunker and has to choose where it goes.' },
  { key: 'MinDistanceBetweenBunkers', type: 'float', category: 'Bunkers', label: 'Minimum Distance Between Bunkers (Unreal units)', min: 0, max: 100000, step: 500, default: 3000.0, help: 'Undocumented by Wildcard.', description: 'How far apart two bunkers must be. Example: at 10000 bunkers end up spread across the map instead of clustered into one fortified block.' },
  { key: 'AllowBunkersInPreventionZones', type: 'bool', category: 'Bunkers', label: 'Allow Bunkers In No-Build Zones', default: false, help: 'Undocumented by Wildcard.', description: 'Permits bunkers inside the areas that normally forbid building. Example: with this on, a bunker can go up next to an obelisk.' },
  { key: 'AllowBunkerModulesInPreventionZones', type: 'bool', category: 'Bunkers', label: 'Allow Bunker Modules In No-Build Zones', default: false, help: 'Undocumented by Wildcard.', description: 'Permits individual bunker modules inside no-build areas. Example: with this on, a module can be added to a bunker that sits partly inside a restricted zone.' },
  { key: 'AllowBunkerModulesAboveGround', type: 'bool', category: 'Bunkers', label: 'Allow Bunker Modules Above Ground', default: false, help: 'Undocumented by Wildcard.', description: 'Permits bunker modules to be placed above ground rather than only below it. Example: with this on, a bunker can extend into a surface building instead of staying buried.' },
  { key: 'AllowRidingDinosInsideBunkers', type: 'bool', category: 'Bunkers', label: 'Allow Riding Inside Bunkers', default: true, help: 'Undocumented by Wildcard.', description: 'Lets players stay mounted inside a bunker. Example: with this off, everyone dismounts at the door and fights inside on foot.' },
  { key: 'AllowDinoAIInsideBunkers', type: 'bool', category: 'Bunkers', label: 'Allow Creature AI Inside Bunkers', default: true, help: 'Undocumented by Wildcard.', description: 'Lets creatures act on their own AI inside a bunker. Example: with this off, tames left in a bunker do not move or defend themselves.' },
  { key: 'EnemyAccessBunkerHPThreshold', type: 'float', category: 'Bunkers', label: 'Enemy Access HP Threshold', min: 0, max: 1, step: 0.01, default: 0.25, help: 'Undocumented by Wildcard. Expressed as a fraction of full health.', description: 'The share of remaining bunker health at which enemies gain access. Example: at 0.25 attackers get in once the bunker is down to a quarter health.' },
  { key: 'BunkerUnderHPThresholdDmgMultiplier', type: 'float', category: 'Bunkers', label: 'Damage Multiplier Below HP Threshold', min: 0, max: 100, step: 0.01, default: 0.05, help: 'Undocumented by Wildcard.', description: 'Scales damage taken once the bunker is below the threshold above. Example: at 0.05 a bunker under the threshold takes very little further damage, so the last quarter of its health is slow to chew through.' },

  // ----------------------------------------------------------- Hexagon Store
  { key: 'bDisableHexagonStore', iniFile: 'game', type: 'bool', category: 'Hexagon Store', label: 'Disable Hexagon Store', default: false, description: 'Turns the Hexagon store off. Example: with this on, mission rewards are worth nothing to spend, so missions become about the loot they drop directly.' },
  { key: 'bHexStoreAllowOnlyEngramTradeOption', iniFile: 'game', type: 'bool', category: 'Hexagon Store', label: 'Hexagon Store Sells Engrams Only', default: false, description: 'Restricts the store to engrams and removes everything else. Example: with this on, hexagons buy knowledge rather than finished gear and resources.' },
  { key: 'HexagonCostMultiplier', iniFile: 'game', type: 'float', category: 'Hexagon Store', label: 'Hexagon Cost Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'Also scales Club Ark token costs in Ascended.', description: 'Scales what things cost in the Hexagon store. Example: at 0.5 everything is half price, so mission rewards go twice as far.' },
  { key: 'BaseHexagonRewardMultiplier', iniFile: 'game', type: 'float', category: 'Hexagon Store', label: 'Hexagon Reward Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'Also scales Club Ark token rewards in Ascended.', description: 'Scales the hexagons missions pay out. Example: at 3.0 a single mission run funds a serious purchase instead of a token one.' },
  { key: 'MaxHexagonsPerCharacter', type: 'int', category: 'Hexagon Store', label: 'Max Hexagons Per Character', min: 0, max: 2000000000, step: 100000, default: 2000000000, help: 'The shipped default is effectively no cap. Official uses 2500000.', description: 'The most hexagons one character may hold. Example: at 2500000 a player cannot bank an unlimited fortune from mission farming.' },

  // ------------------------------------------------------------ World & Time
  { key: 'DayCycleSpeedScale', type: 'float', category: 'World & Time', label: 'Day Cycle Speed Scale', min: 0.01, max: 20, step: 0.01, default: 1.0, help: 'This is the whole cycle. The two below it change the balance of day against night within that cycle.', description: 'Scales how fast the full day-night cycle turns. Example: at 0.5 a complete cycle takes twice as long, so both days and nights are longer.' },
  { key: 'DayTimeSpeedScale', type: 'float', category: 'World & Time', label: 'Day Speed Scale', min: 0.01, max: 20, step: 0.01, default: 1.0, description: 'Scales how quickly in-game daytime passes. Example: at 0.5, daytime hours pass at half speed, making days feel twice as long.' },
  { key: 'NightTimeSpeedScale', type: 'float', category: 'World & Time', label: 'Night Speed Scale', min: 0.01, max: 20, step: 0.01, default: 1.0, description: 'Scales how quickly in-game nighttime passes. Example: at 3.0, night passes three times faster, so nights feel short.' },
  { key: 'DisableWeatherFog', type: 'bool', category: 'World & Time', label: 'Disable Fog', default: false, description: 'Removes fog weather from the map. Example: with this on, a foggy morning no longer cuts visibility to a few metres, which matters most to flyers.' },
  { key: 'ExtinctionEventTimeInterval', type: 'int', category: 'World & Time', label: 'Extinction Event Interval (seconds)', min: 0, max: 31536000, step: 86400, default: '(off)', help: 'This is ARKpocalypse: at the end of each interval the world is wiped. Leave it unset unless that is genuinely the intent.', description: 'Sets how long the world runs before an extinction event wipes it. Example: 2592000 is thirty days, so the map resets monthly.' },

  // ----------------------------------------------------- Creatures & Spawns
  { key: 'ServerAutoForceRespawnWildDinosInterval', type: 'float', category: 'Creatures & Spawns', label: 'Force Wild Respawn On Restart After (seconds)', min: 0, max: 2592000, step: 3600, default: 0.0, help: 'Zero disables it. This is the standard fix for a map whose wild population has been thinned out or crowded by stuck creatures.', description: 'Wipes and respawns all wild creatures at server start once this much time has passed since the last respawn. Example: at 86400 the wild population is refreshed daily, which keeps high-level spawns circulating.' },
  { key: 'ForceGachaUnhappyInCaves', type: 'bool', category: 'Creatures & Spawns', label: 'Gachas Unhappy In Caves', default: true, description: 'Makes Gachas refuse to produce while underground. Example: with this off, a cave becomes a safe farm for Gacha crystals instead of forcing a surface pen.' },
  { key: 'ArmadoggoDeathCooldown', type: 'float', category: 'Creatures & Spawns', label: 'Armadoggo Respawn Cooldown (seconds)', min: 60, max: 604800, step: 60, default: 3600, help: 'Must be greater than zero.', description: 'How long before Armadoggo reappears after taking fatal damage. Example: at 300 it is back within five minutes instead of an hour.' },
  { key: 'YoungIceFoxDeathCooldown', type: 'float', category: 'Creatures & Spawns', label: 'Veilwyn Respawn Cooldown (seconds)', min: 60, max: 604800, step: 60, default: 3600, help: 'Must be greater than zero.', description: 'How long before Veilwyn reappears after taking fatal damage. Example: at 300 it is back within five minutes instead of an hour.' },
  { key: 'CosmoWeaponAmmoReloadAmount', type: 'float', category: 'Creatures & Spawns', label: 'Cosmo Webslinger Reload Amount', min: 0, max: 1000, step: 1, default: 1, description: 'How much webslinger ammo a Cosmo regains per reload tick. Example: at 5 a Cosmo refills its web supply five times as fast.' },
  { key: 'MaxCosmoWeaponAmmo', type: 'float', category: 'Creatures & Spawns', label: 'Cosmo Webslinger Max Ammo', min: -1, max: 10000, step: 1, default: -1, help: 'Minus one keeps the default behaviour, where the maximum scales with the Cosmo\'s level.', description: 'Fixes the webslinger ammo ceiling at a set number instead of scaling it with level. Example: at 100 every Cosmo holds a hundred charges regardless of how it was levelled.' },

  // -------------------------------------------------------------- Server Ops
  { key: 'AutoRestartIntervalSeconds', type: 'float', category: 'Server Ops', label: 'Auto-Restart Interval (seconds)', min: 0, max: 604800, step: 3600, default: '(off)', help: 'Undocumented by Wildcard, and reported to shut the server down rather than bring it back up. Use the Restart button in ARK Overseer instead.', description: 'How long the server runs before restarting itself. Example: at 86400 it cycles once a day, which is one way to keep memory use in check.' },
  { key: 'DontRestoreBackup', type: 'bool', category: 'Server Ops', label: 'Do Not Auto-Restore Backup', default: false, help: 'Only takes effect alongside the -DisableDupeLogDeletes launch flag. Undocumented by Wildcard.', description: 'Stops the server from automatically rolling back to a backup when it finds a corrupted save. Example: with this on, a bad save fails loudly instead of quietly reverting the world to an earlier state.' },
  { key: 'EnableAFKKickPlayerCountPercent', type: 'float', category: 'Server Ops', label: 'Idle Kick Only Above Player Load', min: 0, max: 1, step: 0.01, default: 0.0, help: 'A fraction of Max Players, not a percentage figure. Official uses about 0.9.', description: 'Applies the idle kick only once the server is this full. Example: at 0.9 nobody is kicked for idling until the server is 90% full, so an empty evening does not disconnect anyone.' },
  { key: 'AlwaysNotifyPlayerLeft', type: 'bool', category: 'Server Ops', label: 'Always Announce Players Leaving', default: false, description: 'Announces every disconnect in chat. Example: with this on, everyone sees when a rival logs off, which on a PvP server is genuinely useful intelligence.' },
  { key: 'DontAlwaysNotifyPlayerJoined', type: 'bool', category: 'Server Ops', label: 'Do Not Announce Players Joining', default: false, description: 'Suppresses the join announcement. Example: with this on, players arrive quietly instead of broadcasting their return to the whole server.' },
  { key: 'globalVoiceChat', type: 'bool', category: 'Server Ops', label: 'Global Voice Chat', default: false, description: 'Makes voice chat reach the whole server instead of only nearby players. Example: with this on, someone talking at their base is heard by everyone online.' },
  { key: 'CustomDynamicConfigUrl', type: 'string', category: 'Server Ops', label: 'Dynamic Config URL', maxLength: 500, default: '(none)', help: 'Must be a direct link to a plain dynamicconfig.ini. The server re-reads it periodically, so changes there apply without a restart.', description: 'Points the server at a live config file it re-reads while running, which is how a supported setting can be changed without a restart. Example: host your own dynamicconfig.ini and you can raise taming speed for a weekend event without stopping the server.' },
  { key: 'CustomLiveTuningUrl', type: 'string', category: 'Server Ops', label: 'Live Tuning URL', maxLength: 500, default: '(none)', help: 'Official servers use https://cdn2.arkdedicated.com/asa/livetuningoverloads.json.', description: 'Points the server at a live tuning file for values Wildcard exposes that way. Example: set it to the official URL and this server tracks the same live tuning official servers get.' },
  { key: 'NPCNetworkStasisRangeScalePlayerCountStart', type: 'int', category: 'Server Ops', label: 'Creature Stasis Scaling: Players From', min: 0, max: 200, step: 1, default: 0, help: 'This trio only works when written into the ini, not passed on the command line. All three must be set for any of them to do anything.', description: 'The online player count at which the server starts shrinking how far away creatures stay active. Example: at 10 the server runs at full creature range until the eleventh player joins.' },
  { key: 'NPCNetworkStasisRangeScalePlayerCountEnd', type: 'int', category: 'Server Ops', label: 'Creature Stasis Scaling: Players To', min: 0, max: 200, step: 1, default: 0, help: 'Only works when written into the ini, not on the command line.', description: 'The player count at which the shrinking reaches its floor. Example: at 40 the range has been reduced all the way to the percentage below by the time forty players are on.' },
  { key: 'NPCNetworkStasisRangeScalePercentEnd', type: 'float', category: 'Server Ops', label: 'Creature Stasis Scaling: Floor', min: 0, max: 1, step: 0.01, default: 0.55, help: 'Only works when written into the ini, not on the command line.', description: 'How far the creature activity range is allowed to shrink at full player load. Example: at 0.55 creatures stay active at a little over half the usual distance when the server is busy, which buys back a lot of performance.' },
  { key: 'ListenServerTetherDistanceMultiplier', type: 'float', category: 'Server Ops', label: 'Non-Dedicated Tether Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, help: 'Applies to non-dedicated sessions only, so it does nothing on this dedicated server. Kept here because ARK documents it.', description: 'Scales how far a guest may wander from the host on a non-dedicated session. Example: at 10 a guest can explore ten times further before being dragged back.' },
  { key: 'StructurePreventResourceRadiusMultiplier', type: 'float', category: 'Server Ops', label: 'Structure No-Respawn Radius Multiplier (alt)', min: 0, max: 10, step: 0.05, default: 1.0, help: 'The GameUserSettings twin of the Game.ini setting under Rates. If both are set, both apply, so set one and leave the other alone.', description: 'The same structure resource-regrowth radius control, readable from this file instead of Game.ini. Example: leave this at 1.0 and use the Rates version, or it will multiply against itself.' },
  { key: 'PlatformSaddleBuildAreaBoundsMultiplier', type: 'float', category: 'Server Ops', label: 'Platform Build Area Multiplier', min: 0, max: 100, step: 0.1, default: 1.0, description: 'Scales how far from a platform saddle its structures may extend. Example: at 2.0 a raft base can reach twice as far past the hull.' },
  { key: 'RCONServerGameLogBuffer', type: 'float', category: 'Server Ops', label: 'RCON Game Log Buffer (lines)', min: 0, max: 10000, step: 10, default: 600.0, help: 'Stored as a decimal, but the game counts it in whole lines.', description: 'How many lines of game log the server hands back over RCON. Example: at 100 an RCON client sees only the most recent hundred lines.' },
  { key: 'EnableMeshBitingProtection', type: 'bool', category: 'Server Ops', label: 'Mesh Biting Protection', default: true, help: 'Undocumented by Wildcard.', description: 'Keeps the protection against attacking through the world mesh. Example: with this off, players can shoot into a base through solid rock, which is the exploit this exists to stop.' },
  { key: 'ServerEnableMeshChecking', type: 'bool', category: 'Server Ops', label: 'Mesh Checking', default: false, help: 'Enabled on official. Does nothing if -forcedisablemeshchecking is on the command line. Undocumented.', description: 'Turns on the server\'s mesh checking, which is involved in foliage repopulation. Example: official runs this on, so match it if you want this server to behave the way official does.' },
  { key: 'MaxActiveOutposts', type: 'int', category: 'Server Ops', label: 'Max Active Outposts', min: 0, max: 1000, step: 1, default: '(game default)', help: 'Undocumented by Wildcard; the wiki lists no default or description.', description: 'How many outposts may be active at once. Example: a low value keeps the map from filling with simultaneous outpost activity.' },
  { key: 'MaxActiveCityOutposts', type: 'int', category: 'Server Ops', label: 'Max Active City Outposts', min: 0, max: 1000, step: 1, default: '(game default)', help: 'Undocumented by Wildcard.', description: 'How many city outposts may be active at once. Example: a low value keeps concurrent city outpost activity in check.' },
  { key: 'MaxActiveResourceCaches', type: 'int', category: 'Server Ops', label: 'Max Active Resource Caches', min: 0, max: 1000, step: 1, default: '(game default)', help: 'Undocumented by Wildcard.', description: 'How many resource caches may be active at once. Example: a low value means fewer caches available to find at any given moment.' },
  { key: 'BloodforgeReinforceExtraDurability', type: 'float', category: 'Server Ops', label: 'Bloodforge Reinforce Extra Durability', min: 0, max: 100, step: 0.05, default: 0.3, help: 'Undocumented by Wildcard.', description: 'How much extra durability a Bloodforge reinforcement grants. Example: at 0.6 a reinforced item lasts twice as long past normal as the default gives.' },
  { key: 'BloodforgeReinforceResourceCostMultiplier', type: 'float', category: 'Server Ops', label: 'Bloodforge Reinforce Cost Multiplier', min: 0, max: 100, step: 0.1, default: 3.0, help: 'Undocumented by Wildcard.', description: 'Scales what a Bloodforge reinforcement costs in resources. Example: at 1.0 reinforcing is a third of its default price.' },
  { key: 'BloodforgeReinforceSpeedMultiplier', type: 'float', category: 'Server Ops', label: 'Bloodforge Reinforce Speed Multiplier', min: 0, max: 100, step: 0.1, default: 0.1, help: 'Undocumented by Wildcard.', description: 'Scales how fast a Bloodforge reinforcement completes. Example: at 1.0 reinforcing runs ten times faster than the shipped default.' },

  // ------------------------------------------------------- Chat & Moderation
  { key: 'AdminLogging', type: 'bool', category: 'Chat & Moderation', label: 'Log Admin Commands To Chat', default: false, description: 'Publishes every admin command into in-game chat. Example: with this on, an admin spawning in a creature is visible to everyone, which is the honest option on a server with players who care about fairness.' },
  { key: 'LogChatMessages', type: 'bool', category: 'Chat & Moderation', label: 'Advanced Chat Logging', default: false, help: 'Logs land in ShooterGame/Saved/Logs/ChatLogs/<SessionName>/ as JSON.', description: 'Writes chat to disk as structured logs. Example: with this on, you can go back and read exactly what was said during an argument between two tribes.' },
  { key: 'ChatLogFileSplitIntervalSeconds', type: 'int', category: 'Chat & Moderation', label: 'Chat Log Split Interval (seconds)', min: 45, max: 2592000, step: 45, default: 86400, help: 'Anything below 45 is forced up to 45.', description: 'How often a new chat log file is started. Example: the default 86400 gives one file per day.' },
  { key: 'ChatLogFlushIntervalSeconds', type: 'int', category: 'Chat & Moderation', label: 'Chat Log Flush Interval (seconds)', min: 15, max: 2592000, step: 15, default: 86400, help: 'Anything below 15 is forced up to 15.', description: 'How often buffered chat is written out to the log file. Example: at 60 chat reaches disk within a minute, so a crash loses almost nothing.' },
  { key: 'ChatLogMaxAgeInDays', type: 'int', category: 'Chat & Moderation', label: 'Chat Log Retention (days)', min: -1, max: 3650, step: 1, default: 5, help: 'A negative value means keep forever. Zero is meaningful only in specific cases and is best avoided.', description: 'How long chat logs are kept before deletion. Example: at 30 you have a month of history to look back through.' },
  { key: 'bFilterChat', type: 'bool', category: 'Chat & Moderation', label: 'Filter Chat', default: false, description: 'Filters chat against the bad-words and good-words lists below. Example: with this on and a list loaded, slurs are blocked out of chat automatically.' },
  { key: 'bFilterCharacterNames', type: 'bool', category: 'Chat & Moderation', label: 'Filter Character Names', default: false, description: 'Filters character names against the word lists. Example: with this on, a player cannot join under a deliberately offensive name.' },
  { key: 'bFilterTribeNames', type: 'bool', category: 'Chat & Moderation', label: 'Filter Tribe Names', default: false, description: 'Filters tribe names against the word lists. Example: with this on, an offensive tribe name is rejected at creation.' },
  { key: 'BadWordListURL', type: 'string', category: 'Chat & Moderation', label: 'Bad Word List URL', maxLength: 500, default: '(none)', help: 'Ascended\'s official list is http://cdn2.arkdedicated.com/asa/badwords.txt.', description: 'Where the server fetches its blocked-word list from. Example: point it at your own hosted file and you decide exactly what gets filtered.' },
  { key: 'BadWordWhiteListURL', type: 'string', category: 'Chat & Moderation', label: 'Allowed Word List URL', maxLength: 500, default: '(none)', help: 'Ascended\'s official list is http://cdn2.arkdedicated.com/asa/goodwords.txt.', description: 'Where the server fetches the list of words to spare from filtering. Example: use this to stop an over-eager filter from mangling ordinary words it happens to match.' },
  { key: 'AdminListURL', type: 'string', category: 'Chat & Moderation', label: 'Admin Whitelist URL', maxLength: 500, default: '(none)', help: 'A web-hosted alternative to AllowedCheaterAccountIDs.txt. Refresh interval is set below.', description: 'Where the server fetches its admin whitelist from. Example: host one file and every server in a cluster picks up the same admin list without editing files on each box.' },
  { key: 'UpdateAllowedCheatersInterval', type: 'float', category: 'Chat & Moderation', label: 'Admin Whitelist Refresh (seconds)', min: 3, max: 86400, step: 3, default: 600.0, help: 'Anything below 3 is forced back up.', description: 'How often the remote admin whitelist is re-fetched. Example: at 60 removing someone from the hosted list takes effect within a minute.' },
  { key: 'BanListURL', type: 'string', category: 'Chat & Moderation', label: 'Ban List URL', maxLength: 500, default: '(none)', help: 'Ascended\'s official list is https://cdn2.arkdedicated.com/asa/BanList.txt. Both HTTP and HTTPS work.', description: 'Where the server fetches its ban list from. Example: point it at the official list to inherit Wildcard\'s global bans, or at your own to run your own.' },
  { key: 'CosmeticWhitelistOverride', type: 'string', category: 'Chat & Moderation', label: 'Cosmetic Whitelist URL', maxLength: 500, default: '(none)', help: 'Expects a comma-separated list in the form ModID|dynamic download 0 or 1|allow non-dataonly blueprints.', description: 'Where the server fetches its list of permitted custom cosmetics from. Example: host a list naming three cosmetic mods and only those are allowed on this server.' },
  { key: 'UseCharacterTracker', type: 'bool', category: 'Chat & Moderation', label: 'Character Tracker', default: false, help: 'Can also be set with -disableCharacterTracker on the command line.', description: 'Enables the server\'s character tracking. Example: with this on, the server keeps a record of characters that is useful when investigating a duping report.' },
  { key: 'UseExclusiveList', type: 'bool', category: 'Chat & Moderation', label: 'Whitelist-Only Joining', default: false, help: 'Same behaviour as the -exclusivejoin launch flag. Undocumented by Wildcard.', description: 'Restricts joining to players on the exclusive list. Example: with this on, the server is effectively private, and anyone not whitelisted is refused.' },
  { key: 'AllowHideDamageSourceFromLogs', type: 'bool', category: 'Chat & Moderation', label: 'Allow Hiding Damage Source In Logs', default: true, description: 'Permits the tribe log to omit who dealt the damage. Example: with this off, a tribe log names the attacker outright, which removes the guesswork from a raid.' },

  // --------------------------------------------------------------- Map-Specific
  { key: 'AllowMultipleTamedUnicorns', type: 'bool', category: 'Map-Specific', iniSection: '[Ragnarok]', label: 'Ragnarok: Multiple Tamed Unicorns', default: false, description: 'Allows one wild Unicorn plus any number of tamed ones, instead of exactly one on the map at a time. Example: with this on, taming the Unicorn does not lock everyone else out of ever getting one.' },
  { key: 'UnicornSpawnInterval', type: 'int', category: 'Map-Specific', iniSection: '[Ragnarok]', label: 'Ragnarok: Unicorn Respawn (hours)', min: 0, max: 720, step: 1, default: 24, description: 'How long the game waits before spawning a new wild Unicorn after the current one is killed. Example: at 2 a Unicorn is back within the evening rather than the next day.' },
  { key: 'EnableVolcano', type: 'bool', category: 'Map-Specific', iniSection: '[Ragnarok]', label: 'Ragnarok: Volcano Active', default: true, description: 'Lets the Ragnarok volcano erupt. Example: with this off it never activates, so the volcano is simply a mountain with good metal.' },
  { key: 'VolcanoIntensity', type: 'float', category: 'Map-Specific', iniSection: '[Ragnarok]', label: 'Ragnarok: Volcano Intensity', min: 0.25, max: 20, step: 0.05, default: 1, help: 'Lower is more intense, which is the opposite of what the name suggests. The game floors it at 0.25.', description: 'Scales how violent each eruption is. Example: at 0.25 eruptions are at their most destructive, while higher values calm them down.' },
  { key: 'VolcanoInterval', type: 'int', category: 'Map-Specific', iniSection: '[Ragnarok]', label: 'Ragnarok: Volcano Interval', min: 0, max: 1000, step: 1, default: 0, help: 'Zero means the stock 5000 to 15000 seconds between eruptions. Any higher value acts as a multiplier on that window.', description: 'How long between eruptions. Example: at 4 the gap between eruptions is roughly four times the default, so the volcano is a rare event.' },
  { key: 'bDisableGenesisMissions', iniFile: 'game', type: 'bool', category: 'Map-Specific', label: 'Genesis: Disable Missions', default: false, description: 'Turns off the Genesis mission system. Example: with this on, Genesis becomes an ordinary survival map with no mission terminals to run.' },
  { key: 'bGenesisUseStructuresPreventionVolumes', iniFile: 'game', type: 'bool', category: 'Map-Specific', label: 'Genesis: No Building In Mission Areas', default: false, description: 'Blocks building inside Genesis Part 1 mission areas. Example: with this on, nobody can wall off a mission zone and deny it to other tribes.' },
  { key: 'bDisableDefaultMapItemSets', iniFile: 'game', type: 'bool', category: 'Map-Specific', label: 'Genesis 2: No Tek Suit On Spawn', default: false, description: 'Removes the Tek Suit that Genesis Part 2 hands new spawns. Example: with this on, a fresh survivor starts with nothing, the same as on any other map.' },
  { key: 'bDisableWorldBuffs', iniFile: 'game', type: 'bool', category: 'Map-Specific', label: 'Genesis 2: Disable World Buffs', default: false, help: 'To disable individual buffs rather than all of them, use DisableWorldBuffs in a dynamic config.', description: 'Turns off the server-wide effects Genesis Part 2 missions grant. Example: with this on, completing a mission no longer changes conditions for everyone on the map.' },
  { key: 'bEnableWorldBuffScaling', iniFile: 'game', type: 'bool', category: 'Map-Specific', label: 'Genesis 2: Scale World Buffs', default: false, description: 'Makes mission world effects scale off your server settings instead of adding a flat amount. Example: with this on, a harvest buff on a 5x server is proportional to that rate rather than a fixed bonus that barely registers.' },
  { key: 'WorldBuffScalingEfficacy', iniFile: 'game', type: 'float', category: 'Map-Specific', label: 'Genesis 2: World Buff Scaling Efficacy', min: 0, max: 100, step: 0.1, default: 1.0, help: 'Only matters while world buff scaling above is on.', description: 'How strong the scaled world effects are. Example: at 0.5 mission buffs land at half strength, which keeps them meaningful without being decisive.' },
  { key: 'AllowTekSuitPowersInGenesis', type: 'bool', category: 'Map-Specific', label: 'Genesis: Allow Tek Suit Powers', default: false, description: 'Permits Tek suit abilities in Genesis Part 1, which normally suppresses them. Example: with this on, a survivor can use the Tek jetpack in Genesis instead of wearing the suit as armour only.' },
  { key: 'UseFjordurTraversalBuff', type: 'bool', category: 'Map-Specific', label: 'Fjordur: Realm Teleport', default: false, help: 'Official PvE servers run this on.', description: 'Enables the hold-R biome teleport on Fjordur. Example: with this on, players can jump between Fjordur\'s realms directly instead of finding a portal.' },
  { key: 'ValgueroMemorialEntries', iniFile: 'game', type: 'string', category: 'Map-Specific', label: 'Valguero: Memorial Names', maxLength: 2000, default: '(none)', help: 'Semicolon-separated, no spaces, all on one line: Name1;Name2;Name3;', description: 'The names displayed on the Valguero Memorial, which honours survivors who have ascended. Example: set it to your own tribe\'s roster and the memorial reads their names instead of the defaults.' },

  // --------------------------------------------------------- Message of the Day
  { key: 'Message', type: 'string', category: 'Message of the Day', iniSection: '[MessageOfTheDay]', label: 'Message', maxLength: 1000, default: '(none)', help: 'One line, no quotes. Use \\n where you want a line break.', description: 'The message every player sees once they log in. Example: set it to "Wipe-free since March. Raiding window is 9pm to 9am." and everyone reads that on arrival.' },
  { key: 'Duration', type: 'int', category: 'Message of the Day', iniSection: '[MessageOfTheDay]', label: 'Display Duration (seconds)', min: 1, max: 300, step: 1, default: 20, description: 'How long the message stays on screen at login. Example: at 60 a long notice has time to actually be read.' },

  // ----------------------------------------------------------- Network & Ports
  // Locked: ARK Overseer builds the launch command from the server's own ports and talks to it over
  // RCON, so a value changed here would not match the running server. They stay visible because
  // they are real options with real values. Ports change on the Network page.
  { key: 'Port', type: 'int', category: 'Network & Ports', iniSection: '[SessionSettings]', label: 'Game Port (UDP)', min: 1, max: 65535, step: 1, default: 7777, locked: true, lockedReason: 'Set on the Network page for this server, which also builds the -port launch flag.', description: 'The UDP port the game itself listens on. Example: 7777 is the default, and whatever this is set to has to match the port forwarded on your router.' },
  { key: 'QueryPort', type: 'int', category: 'Network & Ports', iniSection: '[SessionSettings]', label: 'Query Port (UDP)', min: 1, max: 65535, step: 1, default: 27015, locked: true, lockedReason: 'Set on the Network page for this server, which also builds the -QueryPort launch flag.', description: 'The UDP port the server browser uses to find and describe this server. Example: with this blocked, the server runs fine but never appears in anyone\'s server list.' },
  { key: 'RCONEnabled', type: 'bool', category: 'Network & Ports', label: 'RCON Enabled', default: false, locked: true, lockedReason: 'ARK Overseer controls the server over RCON. Turning it off would break Stop, Restart and the save before a shutdown.', description: 'Enables the remote console that ARK Overseer uses to talk to the running server. Example: with this off, nothing outside the game itself can send it a command, ARK Overseer included.' },
  { key: 'RCONPort', type: 'int', category: 'Network & Ports', label: 'RCON Port (TCP)', min: 1, max: 65535, step: 1, default: 27020, locked: true, lockedReason: 'Set on the Network page for this server, so ARK Overseer and the server always agree on it.', description: 'The TCP port the remote console listens on. Example: before a restart, ARK Overseer sends the save command to this port.' },
  { key: 'MultiHome', type: 'string', category: 'Network & Ports', iniSection: '[SessionSettings]', label: 'MultiHome IP Address', maxLength: 45, default: '(none)', locked: true, lockedReason: 'Binding the server to one network interface can put it out of reach of ARK Overseer. To set it anyway, edit the INI file itself.', description: 'Binds the server to a single network interface rather than all of them. Example: on a box with two network cards, this decides which one the server answers on. Leave it blank on an ordinary single-homed machine.' },
  { key: 'ActiveMods', type: 'string', category: 'Network & Ports', label: 'Active Mods', maxLength: 2000, default: '(none)', locked: true, lockedReason: 'Mods are applied through the -mods launch flag, not this key.', description: 'The comma-separated list of mod IDs to load, in priority order. Example: ARK Overseer passes mods on the command line instead, so the list has one source.' },
  { key: 'ActiveMapMod', type: 'string', category: 'Network & Ports', label: 'Active Map Mod', maxLength: 100, default: '(none)', locked: true, lockedReason: 'The map is part of the launch command, so it is chosen with the server, not here.', description: 'The mod ID of a custom map to load. Example: the server launches the map chosen when it was set up, so a map mod set here would disagree with the command line.' },
];

// Options ARK documents that are deliberately not form fields, each with the reason. Every one is
// still settable by editing the INI file itself, and tools/check-coverage.js treats an entry here as
// covered - so the list is a record of decisions, not a list of things that were forgotten.
//
// They all fail the same way as a form control: each is either a bracketed struct or a key that is
// meant to appear on many lines at once, so there is no single value a slider or a text box could
// hold. ARK Overseer's own ini writer is built around one key holding one value (see setIniKey),
// which is exactly the shape these do not have.
const RAW_ONLY_OPTIONS = [
  { key: 'LevelExperienceRampOverrides', iniFile: 'game', category: 'XP & Levels', reason: 'A full level table: every level and its XP requirement, for players and tames, in one bracketed list.', example: 'LevelExperienceRampOverrides=(ExperiencePointsForLevel[0]=10,ExperiencePointsForLevel[1]=25,...)' },
  { key: 'OverridePlayerLevelEngramPoints', iniFile: 'game', category: 'XP & Levels', reason: 'One line per player level, in order, each giving that level\'s engram points. A hundred-odd repeated lines, not one value.', example: 'OverridePlayerLevelEngramPoints=8' },
  { key: 'OverrideEngramEntries', iniFile: 'game', category: 'Items & Crafting', reason: 'One struct per engram, addressed by numeric index, repeated for as many engrams as you are changing.', example: 'OverrideEngramEntries=(EngramIndex=0,EngramHidden=false,EngramPointsCost=10)' },
  { key: 'OverrideNamedEngramEntries', iniFile: 'game', category: 'Items & Crafting', reason: 'The same thing addressed by engram name instead of index, and equally repeatable.', example: 'OverrideNamedEngramEntries=(EngramClassName="EngramEntry_Campfire_C",EngramHidden=true)' },
  { key: 'EngramEntryAutoUnlocks', iniFile: 'game', category: 'Items & Crafting', reason: 'One struct per engram naming the level it unlocks at, repeated per engram.', example: 'EngramEntryAutoUnlocks=(EngramClassName="EngramEntry_Campfire_C",LevelToAutoUnlock=1)' },
  { key: 'ConfigOverrideItemCraftingCosts', iniFile: 'game', category: 'Items & Crafting', reason: 'A nested struct: one item, then a list of resource requirements inside it.', example: 'ConfigOverrideItemCraftingCosts=(ItemClassString="PrimalItemAmmo_ArrowStone_C",BaseCraftingResourceRequirements=((ResourceItemTypeString="PrimalItemResource_Stone_C",BaseResourceRequirement=2.0,bCraftingRequireExactResourceType=false)))' },
  { key: 'ConfigOverrideItemMaxQuantity', iniFile: 'game', category: 'Items & Crafting', reason: 'A nested struct per item, setting that one item\'s stack size.', example: 'ConfigOverrideItemMaxQuantity=(ItemClassString="PrimalItemResource_Thatch_C",Quantity=(MaxItemQuantity=1000,bIgnoreMultiplier=true))' },
  { key: 'ConfigOverrideSupplyCrateItems', iniFile: 'game', category: 'Items & Crafting', reason: 'The deepest nesting ARK has: crate, then item sets, then entries, then class arrays.', example: 'ConfigOverrideSupplyCrateItems=(SupplyCrateClassString="SupplyCrate_Level03_C",MinItemSets=1,...)' },
  { key: 'ExcludeItemIndices', iniFile: 'game', category: 'Items & Crafting', reason: 'One line per excluded item ID, repeated as many times as needed.', example: 'ExcludeItemIndices=1' },
  { key: 'HarvestResourceItemAmountClassMultipliers', iniFile: 'game', category: 'Rates', reason: 'One struct per resource class, so a per-resource harvest table rather than a single multiplier.', example: 'HarvestResourceItemAmountClassMultipliers=(ClassName="PrimalItemResource_Wood_C",Multiplier=2.0)' },
  { key: 'DinoClassDamageMultipliers', iniFile: 'game', category: 'Damage & Resistance', reason: 'One struct per creature class, repeated per creature you are rebalancing.', example: 'DinoClassDamageMultipliers=(ClassName="Rex_Character_BP_C",Multiplier=0.5)' },
  { key: 'DinoClassResistanceMultipliers', iniFile: 'game', category: 'Damage & Resistance', reason: 'Per-creature resistance, same shape as the damage table above.', example: 'DinoClassResistanceMultipliers=(ClassName="Rex_Character_BP_C",Multiplier=0.5)' },
  { key: 'TamedDinoClassDamageMultipliers', iniFile: 'game', category: 'Damage & Resistance', reason: 'Per-creature damage for tames specifically, one struct each.', example: 'TamedDinoClassDamageMultipliers=(ClassName="Rex_Character_BP_C",Multiplier=1.5)' },
  { key: 'TamedDinoClassResistanceMultipliers', iniFile: 'game', category: 'Damage & Resistance', reason: 'Per-creature resistance for tames specifically, one struct each.', example: 'TamedDinoClassResistanceMultipliers=(ClassName="Rex_Character_BP_C",Multiplier=1.5)' },
  { key: 'DinoSpawnWeightMultipliers', iniFile: 'game', category: 'Creatures & Spawns', reason: 'One struct per creature type, weighting how often it spawns relative to the rest.', example: 'DinoSpawnWeightMultipliers=(DinoNameTag=Bronto,SpawnWeightMultiplier=10.0,OverrideSpawnLimitPercentage=true,SpawnLimitPercentage=0.5)' },
  { key: 'NPCReplacements', iniFile: 'game', category: 'Creatures & Spawns', reason: 'A from-and-to pair per replacement, repeated per creature.', example: 'NPCReplacements=(FromClassName="Rex_Character_BP_C",ToClassName="Dodo_Character_BP_C")' },
  { key: 'ConfigOverrideNPCSpawnEntriesContainer', iniFile: 'game', category: 'Creatures & Spawns', reason: 'A spawn container rewrite: nested entry lists inside a named container.', example: 'ConfigOverrideNPCSpawnEntriesContainer=(NPCSpawnEntriesContainerClassString="DinoSpawnEntriesBeach_C",NPCSpawnEntries=(...),NPCSpawnLimits=(...))' },
  { key: 'ConfigAddNPCSpawnEntriesContainer', iniFile: 'game', category: 'Creatures & Spawns', reason: 'The same nested container shape, adding entries rather than replacing them.', example: 'ConfigAddNPCSpawnEntriesContainer=(NPCSpawnEntriesContainerClassString="DinoSpawnEntriesBeach_C",NPCSpawnEntries=(...))' },
  { key: 'ConfigSubtractNPCSpawnEntriesContainer', iniFile: 'game', category: 'Creatures & Spawns', reason: 'The same nested container shape, removing entries.', example: 'ConfigSubtractNPCSpawnEntriesContainer=(NPCSpawnEntriesContainerClassString="DinoSpawnEntriesBeach_C",NPCSpawnEntries=(...))' },
  { key: 'PreventBreedingForClassNames', iniFile: 'game', category: 'Breeding', reason: 'One line per creature class name, repeated per creature you are blocking.', example: 'PreventBreedingForClassNames="Argent_Character_BP_C"' },
  { key: 'PreventDinoTameClassNames', iniFile: 'game', category: 'Taming & Tames', reason: 'One line per creature class name, repeated per creature you are blocking.', example: 'PreventDinoTameClassNames="Argent_Character_BP_C"' },
  { key: 'CheatTeleportLocations', iniFile: 'game', category: 'Server Ops', reason: 'One struct per named location, repeated per teleport you define.', example: 'CheatTeleportLocations=(DisplayName="Hightower",Location=(X=100.0,Y=200.0,Z=300.0))' },
];

export { SETTINGS_FIELDS, RAW_ONLY_OPTIONS, SESSION_NAME_META, NO_QUESTION_MARK, SESSION_NAME_MAX_LENGTH };
